// ALEXtur — данные блога: 20 стран, тексты ru/en/it.
// Подключается как <script src="data/blog-data.js"> до js/blog.js.
// s — обзор (статья) для page article.html, d — слоган-тизер карточки, t — советы.
window.BLOG_COUNTRIES = [
 {i:'italy',n:{ru:'Италия',en:'Italy',it:'Italia'},r:{ru:'Европа',en:'Europe',it:'Europa'},
  d:{ru:'Колизей, каналы Венеции и джелато на набережной.',en:'The Colosseum, Venice’s canals and gelato on the promenade.',it:'Il Colosseo, i canali di Venezia e il gelato in passeggiata.'},
  s:{ru:'Плутали вчера по улочкам, а сегодня гондола несёт вас по Гранд-каналу — так выглядит Италия изнутри: обед на два часа не смущает никого, кофе пьют у стойки, а красота здесь — норма жизни, а не открытка. Венеция стоит на миллионах деревянных свай и не считает это достижением: просто дом. Утро начните с рынка Риальто — торговцы просыпаются раньше толп, и рыба пахнет морем, а не туристическим сезоном. Днём сядьте на вапоретто номер 1, идущий во всю длину Канале-Гранде: за цену чашки кофе вы получите самый честный обзор города с воды. А вечером сбегите со Святого Марка на Дзаттере: пьяцца, аперитив, крики детей и местные, а не фотоаппараты. Италия учит простому правилу: красоту не нужно «снимать», с ней нужно жить по расписанию — завтрак, рынок, обед, сиеста, прогулка. Рим даёт двухтысячелетние слои, Тоскана — пейзажи, от которых замирают ленты новостей, Сицилия — вкус, за который спорят и северяне, и южане. Одна поездка не решит, кто прав, — придётся вернуться. Это лучшая новость из всех возможных.',
     en:'Yesterday you were lost in back lanes; today a gondola carries you down the Grand Canal — that is Italy from the inside: nobody apologises for a two-hour lunch, coffee goes standing, and beauty is simply the norm. Venice stands on millions of wooden piles and never counts it an achievement — it is just home. Start the morning at the Rialto market, where traders wake before the crowds and the fish smells of the sea, not of tourist season. By day, catch vaporetto number 1 the whole length of the Canal Grande: for the price of a coffee you get the most honest view of the city from the water. In the evening, slip away from St Mark’s to the Zattere: a waterfront, an aperitivo, children shouting, locals instead of cameras. Rome gives you two thousand years of layers, Tuscany landscapes that stop the news reels, Sicily a flavour the north and south still argue over. One trip will not settle that argument — you will have to come back. And that is the best news on this page.',
     it:'Ieri vi perdevate nei vicoli, oggi la gondola vi porta sul Canal Grande — ecco l’Italia da dentro: il pranzo di due ore non imbarra nessuno, il caffè si beve in piedi al banco, e la bellezza è norma di vita, non cartolina. Venezia sta su milioni di tronchi di legno e non se ne fa un merito. La mattina cominciate dal mercato di Rialto — i banchi si svegliano prima della folla e il pesce sa di mare, non di alta stagione. Poi il vaporetto numero 1 lungo tutto il Canal Grande: per il prezzo di un caffè avete la vista più onesta della città dall’acqua. La sera fuggite da San Marco verso le Zattere: aperitivo, gridi di bambini e gente del posto. L’Italia insegna una regola semplice: la bellezza non va scattata, va vissuta a orari prestabiliti. Roma offre duemila anni di strati, la Toscana paesaggi che fermano le notizie, la Sicilia un gusto per cui litigano tutti. Una vacanza sola non deciderà chi ha ragione — dovrete tornare. Ed è la miglior notizia possibile.'},
  t:{ru:['Кофе у стойки — дешевле и аутентичнее','Колизей и Ватикан бронируйте заранее','Вечером — passeggiata вместе с местными'],
     en:['Coffee at the bar — cheaper and more authentic','Book the Colosseum and the Vatican ahead','Evenings — join the passeggiata with the locals'],
     it:['Caffè al banco — costa meno ed è più vero','Colosseo e Vaticano: prenotate in anticipo','La sera — passeggiata insieme ai locali']}},
 {i:'russia',n:{ru:'Россия',en:'Russia',it:'Russia'},r:{ru:'Россия',en:'Russia',it:'Russia'},
  d:{ru:'От янтарного Калининграда до вулканов Камчатки.',en:'From amber Kaliningrad to the volcanoes of Kamchatka.',it:'Dal Kaliningrad d’ambra ai vulcani della Kamchatka.'},
  s:{ru:'Одиннадцать часовых поясов — и у каждого свой характер: в Калининграде ещё Европа с черепичными крышами, а на Камчатке уже чёрный лавовый пепел и океан в тумане геотермальных источников. Всю страну за одну поездку не взять, да и не нужно: выберите два контраста и соедините их железной дорогой. Москва утром — Красная площадь до первого автобуса, когда башни ещё стоят в одиночестве. Затем «Сапсан» — и Петербург, где каналы работают лучше любой открытки: с мостами, белыми ночами и ласточками в довесок. Дальше либо Золотое кольцо с куполами над тихими городами, либо Байкал зимой — лёд в полметра толщиной, звенящий под ногами, как стекло. Летом Камчатка отдаёт всё разом: кратеры, медведей на рыбалке и туманы, съедающие горизонт быстрее, чем вы успеваете снимать. Россия не смотрится — она переживается: ночной поезд с чаем в подстаканнике остаётся в памяти надёжнее любого маршрута. Начните с Москвы — и вы сами не заметите, как начнёте планировать Владивосток.',
     en:'Eleven time zones, each with a character of its own: in Kaliningrad it is still Europe with tiled roofs, on Kamchatka black volcanic ash meets an ocean wrapped in geothermal fog. One trip cannot take in the whole country — pick two contrasts and join them by rail. Moscow in the morning, Red Square before the first bus, when the towers still stand alone. Then the Sapsan train, and St Petersburg, where the canals work better than any postcard: bridges, white nights and swifts thrown in for free. From there, either the Golden Ring with its domes over quiet towns, or Baikal in winter — half a metre of ice ringing underfoot like glass. In summer, Kamchatka hands out everything at once: craters, bears fishing, fogs that eat the horizon faster than you can shoot. Russia is not something you look at — it is something you live through. A night train with tea in a holder outlasts any itinerary. Start with Moscow; you will catch yourself planning Vladivostok before you notice.',
     it:'Undici fusi orari, e ognuno ha il suo carattere: a Kaliningrad è ancora Europa coi tetti di coppi, sulla Kamchatka sono già cenere nera di lava e oceano nella nebbia delle sorgenti termali. Tutto il paese in un viaggio non si prende, né conviene: scegliete due contrasti e uniteli in treno. Mosca la mattina — Piazza Rossa prima del primo autobus, quando le torri stanno ancora da sole. Poi il Sapsan, e San Pietroburgo, dove i canali funzionano meglio di qualsiasi cartolina: ponti, notti bianche. Dopo, o l’«Anello d’oro» con le cupole sui paesi tranquilli, o il Bajkal d’inverno — mezzo metro di ghiaccio che canta sotto i piedi come vetro. D’estate la Kamchatka dà tutto insieme: crateri, orsi alla pesca e nebbie che mangiano l’orizzonte. La Russia non si guarda — si vive: il treno notturno col tè nel portabicchieri resta in memoria più di qualunque itinerario. Cominciate da Mosca, e prima che ve ne accorgiate sarete già a pianificare Vladivostok.'},
  t:{ru:['«Сапсан» Москва—Питер экономит целый день','Красную площадь — ранним утром','Ночная электричка — отдельная романтика'],
     en:['The Sapsan Moscow–St Petersburg train saves a whole day','Red Square — early in the morning','The overnight train is a romance of its own'],
     it:['Il Sapsan Mosca—San Pietroburgo risparmia una giornata','Piazza Rossa — la mattina presto','Il treno notturno è una poesia a parte']}},
 {i:'france',n:{ru:'Франция',en:'France',it:'Francia'},r:{ru:'Европа',en:'Europe',it:'Europa'},
  d:{ru:'Лувр, лаванда Прованса и вечерний Париж.',en:'The Louvre, Provençal lavender and Paris at dusk.',it:'Il Louvre, la lavanda di Provenza e Parigi al crepuscolo.'},
  s:{ru:'Франция учит не спешить — и это единственная правильная скорость для этой страны. Круассан на террасе, второй — потому что первый оказался слишком хорошим, Лувр — не за один заход: берите одно крыло в день, иначе глаза и ноги одновременно объявят забастовку. В среду и пятницу музеи заметно свободнее — это проверенный трюк, а не городская легенда. Париж стоит увидеть хотя бы раз, чтобы понять, почему его любят и ворчат на него одновременно: Монмартр с художниками и видами, Сена вечером, когда включает подсветку, и знаменитый нрав парижских водителей, который вы переживёте и даже полюбите. Затем уезжайте на юг: в июле Прованс одевается в фиолетовое, рынки пахнут дыней и травами, а розовый закат над Сеной выглядит как финал хорошего фильма. Хотите замки — вам на Луару; устрицы и скалы — в Нормандию; Ментон и Канны — Ривьера со своим ритмом. Страна живёт контрастами: за три часа на поезде вы меняете эпоху, кухню и пейзаж — а язык гастрономии оставляете себе.',
     en:'France teaches you to slow down, and that is the only speed this country takes seriously. A croissant on a terrace, then a second one because the first turned out too good. The Louvre is never a one-visit affair: take one wing a day, or your eyes and your feet will both call a strike. On Wednesdays and Fridays the museums are noticeably emptier — a tested trick, not an urban legend. Paris deserves at least one visit, to understand why people love it and grumble at it in the same breath: Montmartre with its painters, the Seine switching on its lights at dusk, and the famously feisty Parisian drivers. Then head south: in July Provence dresses in violet, the markets smell of melon and herbs, and a pink sunset over the water looks like the finale of a good film. Want castles — the Loire; oysters and cliffs — Normandy; Menton and Cannes — the Riviera. Three hours by train change the era, the kitchen and the scenery; the language of gastronomy you keep for yourself.',
     it:'La Francia vi insegna a non avere fretta — ed è la velocità giusta per questo paese. Un croissant in terrazza, il secondo perché il primo è venuto troppo buono, il Louvre mai d’un solo fiato: un’ala al giorno, altrimenti occhi e gambe attraversano lo sciopero. Al mercoledì e al venerdì i musei sono visibilmente più liberi — trucco collaudato, non leggenda urbana. Parigi merita almeno una visita, per capire perché la si ama e la si rimprovera allo stesso tempo: Montmartre con artisti e viste, la Senna la sera quando accende le luci, e quel carattere famoso dei conducenti parigini che sopporterete e finirete perfino per amare. Poi scendete al sud: a luglio la Provenza si veste di violaceo, i mercati profumano di melone e d’erbe. Volete castelli — verso la Loira; ostriche e scogli — in Normandia; Mentone e Cannes — la Riviera col suo ritmo. Il paese vive di contrasti: in tre ore di treno cambiate epoca, cucina e paesaggio — e la lingua della gastronomia ve la tenete.'},
  t:{ru:['Музеи — в среду или пятницу, свободнее','Проездной Navigo выгоднее разовых билетов','Прованс — в июле: лаванда в цвету'],
     en:['Museums are freer on Wednesdays and Fridays','A Navigo pass beats single tickets','Provence in July: lavender in bloom'],
     it:['Musei il mercoledì o il venerdì, più liberi','Il pass Navigo conviene più dei biglietti singoli','Provenza in luglio: la lavanda in fiore']}},
 {i:'spain',n:{ru:'Испания',en:'Spain',it:'Spagna'},r:{ru:'Европа',en:'Europe',it:'Europa'},
  d:{ru:'Фламенко, паэлья и невозможный Гауди.',en:'Flamenco, paella and the impossible Gaudí.',it:'Flamenco, paella e l’impossibile Gaudí.'},
  s:{ru:'Испания просыпается в девять вечера: ужин, тапас-бары, разговор до полуночи — и это только начало вечера, а не признак бессонницы. Между делом — Гауди, пляжи, фламенко и рынки, где пахнет хамоном так, что вы пересчитываете обратный билет. Саграда Фамилия строится почти сто сорок лет, и самое интересное не сроки, а то, что завершать её никто не торопится: незаконченное здесь значит живое. Барселона — сеть Готического квартала, где вы гарантированно заблудитесь и будете рады; Мадрид — Прадо, где Веласкес и Босх висят через стену, и ночные очереди за шоколадом с чуррос. Андалусия идёт своим темпом: кордовская мечеть-собор, где христианские колонны растут среди мавританских арок, Севилья с апельсиновыми деревьями и Гранада, из которой виден снежный хребет Сьерра-Невады. Пляжи — от галечных бухт Коста-Бравы до вулканических Канар. Испания отдаёт энергию без сдачи: она не торгуется за ваше внимание — она просто не выключает праздник, когда вы уезжаете.',
     en:'Spain wakes up at nine in the evening: dinner, tapas bars, talk until midnight — and that is only the start of the evening, not insomnia. In between: Gaudí, beaches, flamenco and markets smelling of jamón so strongly you recount your return ticket. The Sagrada Família has been under construction for almost 140 years, and the interesting part is not the deadline but that nobody hurries to finish it: here, unfinished means alive. Barcelona is the lattice of the Gothic Quarter, where you will get lost and be glad of it; Madrid is the Prado, where Velázquez and Bosch hang a wall apart, and queues for churros with chocolate. Andalusia keeps its own tempo: the mosque-cathedral of Córdoba, where Christian columns rise among Moorish arches, Seville with its orange trees, and Granada, with the snowy Sierra Nevada in view. Beaches run from the pebble coves of the Costa Brava to the volcanic Canaries. Spain gives energy without haggling — the holiday keeps running after you leave.',
     it:'La Spagna si sveglia alle nove di sera: cena, bar di tapas, discorsi fino a mezzanotte — ed è solo l’inizio della serata, non un’insonnia. Nel frattempo Gaudí, spiagge, flamenco e mercati che profumano di jamón. La Sagrada Família si costruisce da quasi centoquaranta anni, e la cosa più interessante non sono i tempi, bensì che nessuno ha fretta di finirla: qui l’incompiuto vuol dire vivo. Barcellona è la rete del Quartiere Gotico, dove vi perdete di sicuro e vi farà piacere; Madrid è il Prado, con Velázquez e Bosch a una parete di distanza, e la fila notturna per il cioccolato con i churros. L’Andalusia va col suo passo: la moschea-cattedrale di Cordova, dove le colonne cristiane crescono fra archi moreschi, Siviglia con gli aranci, e Granada, da cui si vede la cresta innevata della Sierra Nevada. Spiagge dalla Costa Brava alle Canarie vulcaniche. La Spagna non contratta la vostra attenzione — semplicemente non spegne la festa quando partite.'},
  t:{ru:['Tapas — это стиль ужина, не закуска','С 14 до 17 — сиеста: магазины закрыты, отдыхайте и вы','В Саграду Фамилию — билеты онлайн заранее'],
     en:['Tapas is a dinner style, not a snack','From 14 to 17 is siesta: shops shut, you rest too','Book Sagrada Família tickets online in advance'],
     it:['Tapas — uno stile di cena, non uno spuntino','Dalle 14 alle 17 è siesta: negozi chiusi, riposate anche voi','Sagrada Família: biglietti online in anticipo']}},
 {i:'greece',n:{ru:'Греция',en:'Greece',it:'Grecia'},r:{ru:'Европа',en:'Europe',it:'Europa'},
  d:{ru:'Белые острова и синее Эгейское море.',en:'White islands and the blues of the Aegean.',it:'Isole bianche e il blu dell’Egeo.'},
  s:{ru:'Греция начинается не с открыток, а с запаха: мастика в кофе, орегано на рыбе и солёный ветер, для которого ни в одном словаре нет хорошего перевода. Все острова хороши — вопрос лишь в том, что вам нужно: движ Миконоса, тишина Паксоса или Санторин, где белые дома будто выцвели под солнцем до состояния совершенства. Афины идите утром: к открытию Акрополя — Парфенон стоит в одиночестве, как декорация, которую режиссёры забыли разобрать. Дальше материк: Метеоры — монастыри на отвесных колоннах скал, где монахи искали тишину так радикально, что строить пришлось в небе. Кухня — отдельная достопримечательность: греческий салат здесь без листьев — так принято, сувлаки с улицы дешевле и честнее ресторанного, а таверна с живым бузуки даёт больше, чем любой музей. Завтрак в Санторини с видом на кальдеру запомнится навсегда. Уезжают из Греции всегда с одним вопросом — на каком острове встретить следующий отпуск.',
     en:'Greece begins not with postcards but with smells: mastika in the coffee, oregano on the fish, and a salt wind no dictionary dares translate. Every island is good — the only question is what you need: the buzz of Mykonos, the hush of Paxos, or Santorini, where the white houses look bleached by the sun into perfection. Do Athens in the morning: reach the Acropolis at opening, when the Parthenon stands alone like stage scenery the directors forgot to strike. Then the mainland: Meteora, monasteries on sheer rock columns, where monks went after silence so radically they had to build in the sky. The cuisine is a sight in itself: Greek salad comes without leaves — that is how it is done; souvlaki from the street is cheaper and more honest than the restaurant version; and a taverna with live bouzouki gives more than a museum. Breakfast in Santorini, with the caldera in front of you, stays with you forever. You always leave asking one question: which island will host the next holiday.',
     it:'La Grecia non comincia dalle cartoline, ma dai profumi: mastice nel caffè, origano sul pesce e il vento salato che nessun dizionario sa tradurre. Tutte le isole sono buone: conta solo cosa cercate — la movida di Mykonos, la quiete di Paxos, o Santorini, dove le case bianche pare siano sbiadite sotto il sole fino alla perfezione. Atene andatela al mattino: all’apertura dell’Acropoli, quando il Partenone sta ancora da solo, come una scenografia dimenticata dai registi. Poi la terraferma: le Meteore, monasteri sui pilastri di roccia a picco, dove i monaci cercavano la quiete tanto radicalmente che hanno costruito in cielo. La cucina è un’attrazione a parte: l’insalata greca qui va senza foglie — tradizione, il souvlaki di strada è più economico e sincero di quello dei ristoranti, e una taverna col bouzouki dal vivo rende più di un museo. La colazione a Santorini davanti alla caldera resta per sempre. Si parte sempre con una domanda sola: su quale isola passare la prossima vacanza.'},
  t:{ru:['Санторини — рассвет, Ойя — закат','Паксос — для тихого отпуска','Греческий салат без листьев — как принято там'],
     en:['Santorini for sunrise, Oia for sunset','Paxos — for the quiet holiday','Greek salad comes without lettuce — as it should'],
     it:['Santorini all’alba, Oia al tramonto','Paxos — per la vacanza tranquilla','L’insalata greca è senza foglie — come vuole la tradizione']}},
 {i:'portugal',n:{ru:'Португалия',en:'Portugal',it:'Portogallo'},r:{ru:'Европа',en:'Europe',it:'Europa'},
  d:{ru:'Трамваи Лиссабона, порт и океан.',en:'The trams of Lisbon, port wine and the ocean.',it:'I tram di Lisbona, il porto e l’oceano.'},
  s:{ru:'Португалия — самая скромная красавица Европы: пока соседи кричат о себе, она стоит в очереди и потому остаётся собой. Лиссабон стоит на семи холмах: трамвай 28 скрипит по рельсам ушедшего века, азулежу расцветает на фасадах в небесно-голубом, а мирадоруш — смотровые — бесплатно открывают город сверху вниз и снизу вверх. За день вы успеете замок Сан-Жоржи, керамику Алфамы и закат на набережной, где океан стучит в скалы, как старый знакомый в дверь. Полдня на поезде — и вы в Порту: двухъярусный мост Дом-Луиш, винные погреба Вила-Нова-ди-Гая на другом берегу, где портвейн пробуют с видом на реку. Если доберётесь до мыса Рока — крайней точки континента — фотографий не нужно: там просто ветер и понятная мысль, что Атлантика начинается здесь. Фадо в Альфаме звучит как разговор, который ведут с памятью; цены — мягче соседей, пастей-де-ната — тёплыми и всегда. Уезжая, вы уже планируете возвращение.',
     en:'Portugal is Europe’s most modest beauty: while the neighbours shout about themselves, it stands quietly in the queue and stays itself. Lisbon sits on seven hills: tram 28 creaks along rails a century old, azulejo tiles bloom sky-blue on the facades, and the miradouros — the lookout terraces — open the city from above and below, free. In one day you can manage St George’s Castle, the ceramics of Alfama and a sunset on the embankment where the ocean knocks on the rocks like an old acquaintance. Half a day by train and you are in Porto: the two-tier Dom Luís bridge, the wine lodges of Vila Nova de Gaia on the far bank, where port is tasted with a river view. If you make it to Cabo da Roca, the continent’s last point, you will not need photos: just wind and the plain thought that the Atlantic begins here. Fado in Alfama sounds like a conversation held with memory. Prices are softer than the neighbours’, the pastéis de nata always warm — and you leave already planning the return.',
     it:'Il Portogallo è la bellezza più timida d’Europa: mentre i vicini gridano il loro nome, lei sta in fila e resta se stessa. Lisbona sta su sette colli: il tram 28 scricchiola sui binari d’altro secolo, gli azulejos fioriscono in azzurro sulle facciate, e i miradouro — i belvedere — regalano gratis la città. In un giorno riuscite in castello di São Jorge, nella ceramica dell’Alfama e nel tramonto sul lungomare, dove l’oceano bussa sugli scogli come un vecchio amico alla porta. Mezzo giorno in treno e siete a Porto: il ponte Dom Luís a due piani, le cantine di Vila Nova de Gaia sull’altra riva, dove si assaggia il porto col fiume davanti. Se arrivate a Cabo da Roca, punto estremo del continente, le foto non servono: lì c’è solo vento e un pensiero chiaro — l’Atlantico comincia qui. Il fado nell’Alfama suona come una conversazione colla memoria; i prezzi sono più morbidi di quelli dei vicini, i pastéis de nata caldi, e sempre. Partendo, pianificate già il ritorno.'},
  t:{ru:['Трамвай 28 — рано утром, без давки','Пастей-де-ната — тёплыми, обязательно','Лиссабон холмистый — обувь с подошвой'],
     en:['Tram 28 — early, before the crush','Pastéis de nata — warm, always','Lisbon is hilly — wear grippy shoes'],
     it:['Tram 28 — presto, senza folla','Pasteis de nata — caldi, sempre','Lisbona è collinosa — servono scarpe adatte']}},
 {i:'swiss',n:{ru:'Швейцария',en:'Switzerland',it:'Svizzera'},r:{ru:'Европа',en:'Europe',it:'Europa'},
  d:{ru:'Альпийские поезда, фондю и озёра изумруда.',en:'Alpine trains, fondue and emerald lakes.',it:'Treni alpini, fondue e laghi smeraldo.'},
  s:{ru:'Швейцария собрана из открыток, но без фальши: озёра действительно изумрудные, коровы носят колокольчики, а поезда приходят, как гиревые часы, — с точностью до секунды. Bernina Express — причина взять отпуск сам по себе: поезд взбирается в горы так, что пассажиры в одно и то же мгновение забывают про телефоны, а панорамные окна заканчиваются в считаных метрах от отвесных склонов. Цюрих удобен для старта — озеро, тихая старая часть, шоколадные прилавки серьёзнее большинства музеев. Женева даёт международный шлейф и фонтан на 140 метров, Люцерн — деревянный Часовенный мост XIV века и вид на озеро, который вы не поверите с первого взгляда, пока не убедитесь лично. Фуникулёры доезжают туда, где фондю звучит уместнее всего, а вода в городских фонтанах — питьевая: смело пейте, это тут — норма. Дорого — да. Но впечатления здесь продаются метрами высоты, и каждый чек хотя бы объясним.',
     en:'Switzerland is assembled from postcards, yet without a trace of fake: the lakes really are emerald, the cows do wear bells, and the trains arrive like a well-regulated watch — to the second. The Bernina Express is a reason to book leave all by itself: the way the train climbs, passengers forget their phones in the same moment, and the panoramic windows end within metres of sheer slopes. Zürich is a good launchpad — the lake, a quiet old town, chocolate counters that out-argue most museums. Geneva brings an international air and a fountain a hundred and forty metres high; Lucerne offers the wooden Chapel Bridge of the fourteenth century and a lake view you will refuse to believe until you have checked it in person. Funiculars reach the heights where fondue sounds most fitting, and the water in city fountains is drinkable: help yourself — that is the local norm. Expensive, yes. But here impressions are sold by metres of altitude, and every bill is at least explainable.',
     it:'La Svizzera è assemblata di cartoline, ma senza falsità: i laghi sono davvero color smeraldo, le mucche portano campanelle e i treni arrivano come orologio, al secondo. Il Bernina Express da solo è una ragione in più per la vacanza: il treno si arrampica in montagna in modo che tutti i passeggeri nello stesso istante dimenticano i telefoni, e i finestrini panoramici finiscono a pochi metri dalle pareti a picco. Zurigo è comoda per partire: il lago, la città vecchia tranquilla, banchi di cioccolato più seri di gran parte dei musei. Ginevra porta un’aura internazionale e il getto d’acqua a 140 metri; Lucerna il ponte della Cappella del Trecento, di legno, e una vista sul lago che a prima occhiata non crederete — finché non verificate di persona. Le funivie arrivano là dove la fondue suona più adatta, e l’acqua delle fontane urbane è potabile: bevete pure sereni, qui è norma. Caro — sì. Ma le emozioni qui si vendono a metri di quota, e ogni conto almeno lo spiega.'},
  t:{ru:['Half Fare Card экономит на поездах','Вода из фонтанов — питьевая, смело','Фондю лучше пробовать на высоте'],
     en:['A Half Fare Card pays off on trains','Fountain water is drinkable — help yourself','Try fondue at altitude'],
     it:['L’Half Fare Card conviene sui treni','L’acqua delle fontane è potabile — state sereni','La fondue la gustate in quota']}},
 {i:'austria',n:{ru:'Австрия',en:'Austria',it:'Austria'},r:{ru:'Европа',en:'Europe',it:'Europa'},
  d:{ru:'Вальсы Вены и кофе со штруделем.',en:'The waltzes of Vienna and coffee with strudel.',it:'I valzer di Vienna e il caffè con lo strudel.'},
  s:{ru:'Австрия идет как хорошая вещь из антикварной лавки: аккуратно, с историей и без единой лишней детали. Вена закрывает всё разом: Шёнбрунн с садами, кофейни из списка ЮНЕСКО, где официант запоминает ваш кофе с первого раза, и вальс, который здесь не достопримечательность, а воздух. Хофбург и Стефансдом отрабатывают историю, а вечером заказывайте штрудель тёплым, с ванильным соусом, и сидите на террасе, где играют живьём. Второй слой — Зальцбург: родина Моцарта, крепость над рекой и улицы, которые «Звуки музыки» сделали знаменитыми. Третий — альпийская глубинка: деревни с молоком «прямо из-под коровы», озёра Зальцкаммергута и Хальштат на отвесном склоне, где деревянные дома в три ряда смотрят на воду. S-Bahn довезёт до аутентичных пригородов за карманные деньги. Вена идеально идёт под позднюю осень: когда в других столицах уже скучно, здесь начинается сезон кофеен. Страна маленькая, но плотная — как хороший штрудель.',
     en:'Austria behaves like a good piece from an antique shop: neat, with a history, no detail too many. Vienna covers it all at once: Schönbrunn with its gardens, UNESCO-listed coffee houses where the waiter remembers your order from the first cup, and the waltz, which here is not an attraction but just air. The Hofburg and St Stephen’s Cathedral handle the history, and in the evening you order the strudel warm, with vanilla sauce, and sit on a terrace with a live band. The second layer is Salzburg: Mozart’s birthplace, a fortress above the river and streets The Sound of Music made famous. The third is alpine countryside: villages with milk straight from the cow, the lakes of the Salzkammergut and Hallstatt on its sheer slope, wooden houses in three rows looking down at the water. The S-Bahn takes you to the authentic suburbs for pocket money. Vienna goes best with late autumn: when other capitals go dull, the coffee-house season starts here. A small country, but dense — like good strudel.',
     it:'L’Austria va come una buona cosa d’antiquariato: curata, con storia e senza un dettaglio di troppo. Vienna risolve tutto insieme: Schönbrunn coi giardini, le caffetterie patrimonio UNESCO, dove il cameriere memorizza il vostro caffè dalla prima volta, e un valzer che qui è aria. Hofburg e Stefansdom fanno la parte della storia, e la sera ordinate lo strudel caldo, con la salsa alla vaniglia, seduti in terrazza dove suonano dal vivo. Secondo strato — Salisburgo: la patria di Mozart, la fortezza sopra il fiume e le strade che «Tutti insieme appassionatamente» hanno reso celebri. Terzo — la profonda provincia alpina: paesi col latte «appena munto», i laghi del Salzkammergut e Hallstatt col pendio a picco, case di legno su tre filze. La S-Bahn porta nei sobborghi autentici per soldi da tasca. Vienna si sposa benissimo col tardo autunno: quando nelle altre capitali comincia la noia, qui parte la stagione dei caffè. Il paese è piccolo, ma denso — come uno strudel ben riuscito.'},
  t:{ru:['Штрудель заказывайте тёплым с ванильным соусом','S-Bahn довезёт до аутентичных пригородов','Вена идеально идёт под позднюю осень'],
     en:['Order strudel warm, with vanilla sauce','The S-Bahn reaches the authentic suburbs','Vienna pairs perfectly with late autumn'],
     it:['Strudel caldo, con salsa alla vaniglia','La S-Bahn porta nei sobborghi autentici','Vienna si sposa con il tardo autunno']}},
 {i:'germany',n:{ru:'Германия',en:'Germany',it:'Germania'},r:{ru:'Европа',en:'Europe',it:'Europa'},
  d:{ru:'Замки Баварии и молодой Берлин.',en:'Bavaria’s castles and young Berlin.',it:'I castelli della Baviera e Berlino giovane.'},
  s:{ru:'Германия — про контрасты, и она не делает вид, что это конфликт. Нойшванштайн стоит в альпийском лесу как декорация из сказки — Людвиг II строил его по мотивам Вагнера, и вышло прекрасное безумие; билеты берите за неделю. Берлин — противоположный полюс: остатки Стены на Бернауэр-штрассе, East Side Gallery с граффити вместо бетонных панелей, клубы, куда вы, возможно, не попадёте, — и это по-берлински честный фильтр. Поезда удобны и пунктуальны, хлеб здесь — отдельная цивилизация с сотнями сортов, а летние пивные сады под каштанами — лучший общественный диван Европы. Добавьте Дрезден с восстановленной Фрауэнкирхе — камни разобрали по номерам и сложили обратно, Кёльн с собором, который строили шесть веков, и долину Рейна с замком на каждом изгибе реки. Welcome Card в Берлине окупается на транспорте и музеях. Германия не притворяется безупречной, и от этого отдых идёт без напряжения: всё работает, всё удивляет — и всегда остаётся время на второй бокал.',
     en:'Germany is about contrasts and does not pretend they are a conflict. Neuschwanstein stands in an alpine wood like scenery from a storybook — Ludwig II built it on Wagner’s motifs, and produced beautiful madness; take tickets a week ahead. Berlin is the opposite pole: remains of the Wall on Bernauer Strasse, the East Side Gallery and its graffiti, clubs you may not get into — and that is Berlin’s honest filter. Trains are easy and punctual, bread is a civilisation of its own with hundreds of kinds, and the beer gardens under the chestnuts are Europe’s best public sofa. Add Dresden with its rebuilt Frauenkirche — the stones were numbered and put back one by one — Cologne with a cathedral that took six centuries, and the Rhine valley with a castle at every bend. Berlin’s Welcome Card pays off on transport and museums. Germany does not act flawless, and that is why the trip runs without strain: everything works, everything surprises, and there is always time for a second glass.',
     it:'La Germania è fatta di contrasti, e non finge che sia un conflitto. Il Neuschwanstein sta nel bosco alpino come una scenografia da fiaba — Ludwig II lo volle sulle note di Wagner: follia bellissima; i biglietti prendeteli una settimana avanti. Berlino è il polo opposto: i resti del Muro sulla Bernauer Straße, l’East Side Gallery coi graffiti al posto del cemento, i club dove magari non entrerete — un filtro onesto, alla berlinese. I treni sono comodi e puntuali, il pane è una civiltà a parte con centinaia di varietà, e i birrari d’estate sotto i castagni sono il miglior divano pubblico d’Europa. Aggiungete Dresda con la Frauenkirche ricostruita — pietra smontata e risalita pezzo per pezzo —, Colonia col Duomo costruito in sei secoli, e la valle del Reno con un castello su ogni curva. A Berlino la Welcome Card si ripaga su trasporti e musei. Non finge di essere impeccabile, e il viaggio va senza tensione: tutto funziona, tutto stupisce — e resta sempre tempo per il secondo bicchiere.'},
  t:{ru:['Neuschwanstein — билеты за неделю','В Берлине — берите Welcome Card','Пивные сады — это летом и непременно'],
     en:['Neuschwanstein tickets — a week ahead','Get the Welcome Card in Berlin','Beer gardens: in summer, and non-negotiable'],
     it:['Neuschwanstein: biglietti una settimana prima','A Berlino prendete la Welcome Card','Il biergarten — estate e senza scuse']}},
 {i:'uk',n:{ru:'Великобритания',en:'United Kingdom',it:'Regno Unito'},r:{ru:'Европа',en:'Europe',it:'Europa'},
  d:{ru:'Туман, чай и Биг-Бен.',en:'Rain, tea and Big Ben.',it:'Pioggia, té e Big Ben.'},
  s:{ru:'Британия — это про характер, а характер в рекламе не показывают. Первый Лондон: Sky Garden за бесплатной высотой (бронь за неделю), рынок Боро на завтрак, вечер на Саутбэнке под фонарями, где Темза ведёт себя как кино. Метро с Oyster-картой вы освоите за день, а Британский музей — бесплатный и всегда: от Розеттского камня до мумий, под которыми дети залипают часами. За городом — Эдинбург: замок на базальтовой скале и Ройал-Майл, идущая сверху вниз, как лестница истории; Хайлендс с озёрами и одиночеством в подарок; Йорк — ради собора, Оксфорд — ради колледжей. Погода не повод для обиды: возьмите плащ, сядьте на верхний этаж двухэтажного автобуса и смотрите город сквозь стекло — через час вы уже играете на его инструменте. Чай в четыре — ритуал, а не клише. За городом не забудьте Котсуолдс — мёдовые каменные деревни, где время идёт пешком. Британия отдаёт вам жанр и словарь к нему.',
     en:'Britain is about character, and character is not shown in adverts. First, London: the Sky Garden for a free dose of height (book a week ahead), Borough Market for breakfast, an evening on the South Bank under lamps where the Thames behaves like cinema. With an Oyster card you will master the Tube in a day, and the British Museum is free and always: from the Rosetta Stone to mummies the children disappear under for hours. Out of town — Edinburgh: a castle on a basalt cliff and the Royal Mile running downhill like a staircase of history; the Highlands with lochs and solitude thrown in; York for the cathedral, Oxford for the colleges. Do not take the weather personally: take a mac, climb to the top deck of a double-decker and watch the city through the glass — within the hour you are fluent in the genre. Tea at four is a ritual, not a cliché. And remember the Cotswolds — honey-stone villages where time travels on foot. Britain hands you a genre and the vocabulary to go with it.',
     it:'La Gran Bretagna è questione di carattere, e il carattere non si vede nelle pubblicità. Primo, Londra: la Sky Garden per l’altezza gratis (prenotate una settimana prima), il mercato di Borough per colazione, la sera al Southbank sotto i lampioni, dove il Tamigi si comporta da film. Con la Oyster card la metro la capite in un giorno, e il British Museum è gratis e sempre: dalla Pietra di Rosetta alle mummie davanti a cui i bambini incollano per ore. Fuori città — Edimburgo: il castello sul basalto e la Royal Mile che scende come una scala della storia; le Highlands coi laghi e la solitudine in regalo; York per la cattedrale, Oxford per i college. Del meteo non prendetevela: impermeabile, piano superiore di un autobus, e la città si racconta da lì — dopo un’ora suonate già il suo strumento. Il tè alle quattro è un rituale, non un cliché. E ricordate i Cotswolds: borghi di pietra color miele, dove il tempo va a piedi. La Gran Bretagna vi consegna un genere e il vocabolario.'},
  t:{ru:['Sky Garden — бесплатный вид с крыши','Oyster Card — метро проще всего','Чай в четыре — ритуал, не клише'],
     en:['Sky Garden — a free rooftop view','Oyster card — the easiest route through the Tube','Tea at four is a ritual, not a cliché'],
     it:['Sky Garden — vista dal tetto gratis','Oyster card — la metropolitana diventa facile','Il té alle quattro è rito, non cliché']}},
 {i:'netherlands',n:{ru:'Нидерланды',en:'the Netherlands',it:'Paesi Bassi'},r:{ru:'Европа',en:'Europe',it:'Europa'},
  d:{ru:'Мельницы, тюльпаны, каналы Амстердама.',en:'Windmills, tulips and the canals of Amsterdam.',it:'Mulini, tulipani, canali di Amsterdam.'},
  s:{ru:'Нидерланды — велосипедная симфония: страна, где двухколёсных больше, чем людей, и это не гипербола, а дорожный план. Амстердам даёт каналы, которые вечером подсвечиваются так убедительно, что хочется остаться; Рейксмузеум — с «Ночным дозором» в полный рост; Йордан — с лавками, котиками на порогах и сыром, которого вы увезёте больше, чем планировали. Кёкенхоф работает только в апреле—мае: потом поле закрывают до следующего года, и это честно — у цветов свой календарь. Киндердайк — 18 ветряных мельниц в ряд; Роттердам — обратный полюс: кубические дома, современная архитектура и порт, который видно даже с орбиты. Утрехт с двухуровневыми каналами и террасами у самой воды — тихий фаворит на вечер. Велосипедов тут больше, чем дорог: смотрите под колёса и не спорьте с правилами. Плоская местность прощает даже новичкам 30 км за день. Ветер дует горизонтально и всегда против ваших планов — берите слои и не планируйте точные времена.',
     en:'The Netherlands is a bicycle symphony: a country with more two-wheelers than people, and that is not a figure of speech but a road plan. Amsterdam gives you canals that light up so persuasively at night you want to stay; the Rijksmuseum holds the Night Watch at full height; the Jordaan has little shops, cats on doorsteps and more cheese than you planned to carry home. Keukenhof runs only in April and May: after that the field closes until next year, which is fair — flowers have their own calendar. Kinderdijk lines up its windmills in a long row; Rotterdam is the opposite pole: cube houses, modern architecture and a port visible from orbit. Utrecht, with two-level canals and terraces at water level, is the quiet favourite for the evening. Bikes outnumber the roads here: watch your wheels and do not argue with the rules. Flat ground forgives even beginners thirty kilometres a day; the wind blows horizontally and always against your plans — wear layers and keep the timetable loose.',
     it:'I Paesi Bassi sono una sinfonia in bicicletta: un paese dove ci sono più biciclette che persone — non iperbole, piano viario. Amsterdam dà i canali, che la sera si illuminano finché vi viene voglia di restare; il Rijksmuseum con la «Ronda di notte» a grandezza naturale; il Jordaan con botteghe, gatti sui gradini e un formaggio di cui porterete via più del previsto. Il Keukenhof apre solo in aprile–maggio: poi il campo si chiude fino all’anno dopo, è giusto — i fiori hanno il loro calendario. Kinderdijk — 18 mulini in fila; Rotterdam è il polo opposto: case cubiche, architettura contemporanea e un porto visto persino dall’orbita. Utrecht, coi canali a due livelli e le terrazze a filo d’acqua, è il favorito silenzioso della sera. Le bici qui sono più delle strade: guardate sotto le ruote e non litigate con le regole. Il piano perdona persino ai principianti 30 km al giorno. Il vento soffia in orizzontale e sempre contro i vostri piani — vestitevi a strati, non fissate orari precisi.'},
  t:{ru:['Велосипед напрокат — главный транспорт','Кёкенхоф — только апрель–май','Смотрите под колёса: велосипедисты везде'],
     en:['A rental bike is the main transport','Keukenhof — April to May only','Watch for bikes: cyclists are everywhere'],
     it:['La bicicletta a noleggio è il mezzo principale','Keukenhof — solo aprile-maggio','Occhio alle bici: i ciclisti sono ovunque']}},
 {i:'norway',n:{ru:'Норвегия',en:'Norway',it:'Norvegia'},r:{ru:'Европа',en:'Europe',it:'Europa'},
  d:{ru:'Фьорды и северное сияние.',en:'Fjords and the northern lights.',it:'Fiordi e aurora boreale.'},
  s:{ru:'Норвегия — там, где заканчиваются дороги и начинаются фьорды: скалы уходят в воду отвесно, вода в них такого сине-зелёного оттенка, что фотоаппарат отказывается это признавать. Лофотены — архипелаг с хижинами-рорбу на сваях, где кофе на террасе с видом на море входит в программу, а тресковые гирлянды вялятся под крышами, как флаги рыбацкой цивилизации. Фломская железная дорога — лучший первый фьорд: поезд карабкается вверх через водопады и туннели, а плато в конце кажется отдельной страной. Осенью и зимой — сияние: с сентября по март, бесплатное и щедрое, как полярная ночь; слой за слоем одевайтесь, погода меняется быстрее, чем вы выбираете объектив. Осло — спокойный финал: по крыше оперного театра можно ходить, а в музее Фрама — зайти в настоящий борт полярного судна. Дорого — да. Но это цена за ландшафт, который не нарисован, а построен тектоникой плит, и он не продаётся нигде ещё.',
     en:'Norway is where the roads end and the fjords begin: the rock drops sheer into the water, and the water is a blue-green shade the camera refuses to admit it cannot capture. The Lofoten Islands are an archipelago of rorbu huts on stilts, where coffee on a terrace facing the sea counts as a programme item, and cod hangs drying under the roofs like the flags of a fishing civilisation. The Flåm railway is the best first fjord: the train hauls itself up through waterfalls and tunnels, and the plateau at the top feels like a separate country. In autumn and winter there is the aurora: from September to March, free and as generous as the polar night itself. Dress in layers — the weather turns faster than you can choose a lens. Oslo is a calm finale: you can walk on the roof of the opera house, and at the Fram Museum step aboard a real polar vessel. Expensive, yes. But that is the price of a landscape not painted but built by tectonic plates — and it is not on sale anywhere else.',
     it:'La Norvegia è dove finiscono le strade e cominciano i fiordi: le pareti vanno nell’acqua a picco, e l’acqua è di quel color verde-azzurro che la macchina fotografica si rifiuta di ammettere. Le Lofoten — l’arcipelago dei rorbu su palafitte, dove il caffè in terrazza davanti al mare entra nel programma, e le ghirlande di merluzzo essiccano sotto le tettoie come bandiere di una civiltà della pesca. La ferrovia di Flåm è il miglior primo fiordo: il treno si arrampica attraverso cascate e gallerie, e l’altopiano in cima sembra un paese a parte. In autunno e in inverno viene l’aurora boreale: da settembre a marzo, gratis e generosa come la notte polare; vestitevi a strati, il tempo cambia più in fretta di quanto scegliate l’obiettivo. Oslo — un finale tranquillo: sul tetto dell’Opera si può camminare, e al museo del Fram entrate nel vero fianco di una nave polare. Caro — sì. Ma è il prezzo di un paesaggio non dipinto, costruito dalle placche tettoniche, e non si vende da nessun’altra parte.'},
  t:{ru:['Сияние активнее с сентября по март','Фломская железная дорога — лучший первый фьорд','Слои одежды: погода меняется за час'],
     en:['The aurora is liveliest September to March','The Flåm railway is the best first fjord','Dress in layers — the weather turns hourly'],
     it:['L’aurora luccica più da settembre a marzo','La ferrovia di Flåm è il fiordo migliore per iniziare','Vestitevi a strati — il meteo cambia ogni ora']}},
 {i:'croatia',n:{ru:'Хорватия',en:'Croatia',it:'Croazia'},r:{ru:'Европа',en:'Europe',it:'Europa'},
  d:{ru:'Дубровник и тысяча островов.',en:'Dubrovnik and a thousand islands.',it:'Dubrovnik e mille isole.'},
  s:{ru:'Хорватия — Адриатика в лучшей форме: стены Дубровника, вода прозрачная как стекло и тысяча островов в придачу. Стены идут по периметру старого города — два километра, сорок минут; к открытию, в 8 утра, — без жары и без толп, вид с красными крышами и яхтами внизу. Внутри всё компактно: улица Страдун отполирована пешеходами столетий, улочки уходят вверх ступеньками, и вы рано или поздно потеряете направление — тут теряются с четырнадцатого века, это местный жанр. За городом — Плитвицкие озёра: шестнадцать водопадов на один парк, деревянные настилы прямо над бирюзовой водой; приходите к открытию и идите против толпы. Острова: Хвар с лавандой и виноградниками, Корчула — по легенде, родина Марко Поло, Лопуд — вовсе без машин. Лодка к островам дешевле с пристани, чем через отель, а вечером — местное вино на террасе: с видом, без спешки и с честной ценой. Хорватия не кричит о себе — и в этом её хорошая форма.',
     en:'Croatia is the Adriatic in its best form: the walls of Dubrovnik, water clear as glass and a thousand islands thrown in. The walls run right around the old town — two kilometres, forty minutes; come at eight, at opening, with no heat and no crowds, the roofs red and the yachts below. Inside, it is compact: the Stradun polished by centuries of pedestrians, lanes climbing in steps, and sooner or later you lose your bearings — people have got lost here since the fourteenth century, a local genre. Out of town, the Plitvice Lakes: sixteen waterfalls in one park and wooden walkways right above turquoise water; arrive at opening and walk against the crowd. The islands: Hvar with lavender and vineyards, Korcula — by legend Marco Polo’s birthplace, Lopud without a single car. A boat to the islands costs less from the pier, and in the evening there is local wine on a terrace, with a view and an honest bill. Croatia does not shout about itself — that is its good form.',
     it:'La Croazia è l’Adriatico al suo meglio: le mura di Dubrovnik, un’acqua trasparente come vetro e mille isole. Le mura corrono per il perimetro della città vecchia — due chilometri, quaranta minuti; all’apertura, alle 8 del mattino, senza calura e senza folla, coi tetti rossi in vista. Dentro tutto è compatto: lo Stradun levigato dai piedi di secoli di passanti, i vicoli che salgono a gradini, e prima o poi perdete l’orientamento — qui ci si perde dal Quattordicesimo secolo, è un genere locale. Fuori città — i laghi di Plitvice: sedici cascate per un solo parco, passerelle di legno direttamente sull’acqua turchese; venite all’apertura e camminate controcorrente. Le isole: Hvar tra lavanda e vigne, Korčula che la leggenda fa patria di Marco Polo, Lopud senza automobili. La barca per le isole costa meno dalla banchina che attraverso l’hotel, e la sera vino locale in terrazza: con la vista, senza fretta e col conto onesto. La Croazia non urla di sé — ed è qui la sua buona forma.'},
  t:{ru:['Стены Дубровника — к открытию, в 8 утра','Лодка к островам — дешевле с пристани','Вечером — местное вино на террасе: дешевле и с видом на море'],
     en:['Walk Dubrovnik’s walls right at opening, 8 am','Island boats are cheaper from the pier','Evenings — local wine on the terrace: cheaper, with a sea view'],
     it:['Le mura di Dubrovnik — all’apertura, alle 8','La barca per le isole — più economica dalla banchina','La sera — vino locale in terrazza: più economico, con vista mare']}},
 {i:'turkey',n:{ru:'Турция',en:'Turkey',it:'Turchia'},r:{ru:'Азия',en:'Asia',it:'Asia'},
  d:{ru:'Стамбул между двух материков, шары Каппадокии.',en:'Istanbul straddling two continents, the balloons of Cappadocia.',it:'Istanbul tra due continenti, le mongolfiere di Cappadocia.'},
  s:{ru:'Турция — два отпуска в одном: утром вы пьёте чай из тюльпанного стакана между Европой и Азией с видом на Босфор, а на рассвете следующего дня стоите в корзине воздушного шара над Каппадокией. Стамбул работает слоями: Айя-София, где века сменяют друг друга прямо в стенах; Голубая мечеть с изразцами; цистерна Базилика — подземный зал на 336 колоннах, в воде которого плавают рыбы, а отражения ходят по потолку. Гранд-базар уговаривает вас с искренностью, которой позавидуют театральные труппы. Одна монета Истамбулкарта открывает все паромы: за цену проезда вы получаете лучший вид на город с воды — с чайкой в кадре. Каппадокия — вулканический рельеф, в котором выдолбили целые города: подземный Деринкую уходит на восемь этажей вниз, а долина Гёреме рассыпана каменными «трубами» и церквями с фресками. Шары летают на первом рассвете — бронируйте заранее. Свежевыжатый сок с улицы, севиче с рынка, рыба у Босфора — и лучшее соотношение цены и впечатления во всём списке.',
     en:'Turkey is two holidays in one: in the morning you drink tea from a tulip-shaped glass between Europe and Asia with the Bosphorus in front of you, and at the next dawn you are in a balloon basket above Cappadocia. Istanbul works in layers: Hagia Sophia, where centuries succeed each other inside the walls; the Blue Mosque with its tiles; the Basilica Cistern, an underground hall on 336 columns where fish glide and reflections walk the ceiling. The Grand Bazaar negotiates with a sincerity theatre troupes would envy. One Istanbulkart opens every ferry: for the price of a ride you get the best view of the city from the water — seagull included. Cappadocia is volcanic relief carved into whole cities: the underground Derinkuyu goes eight storeys down, and the Göreme valley is scattered with stone chimneys and frescoed churches. The balloons fly at first dawn — book early. Street-squeezed orange juice, fish by the Bosphorus — and the best value-for-impression ratio in this whole list.',
     it:'La Turchia sono due vacanze in una: al mattino bevete il tè dal bicchiere a tulipano fra Europa e Asia, con vista sul Bosforo, e all’alba del giorno dopo state già nel cestino di una mongolfiera sulla Cappadocia. Istanbul lavora a strati: l’Ayasofya, dove i secoli si passano il testimone nelle mura; la Moschea Azzurra con le maioliche; la Cisterna Basilica — salone sotterraneo su 336 colonne, pesci in acqua e riflessi sul soffitto. Il Grande Bazar vi convince con sincerità da invidiare a una compagnia teatrale. Con una Istanbulkart aprite tutti i traghetti: col prezzo d’un urbano avete la miglior vista della città dall’acqua — gabbiano in quadro. La Cappadocia è un rilievo vulcanico con città intere scavate: Derinkuyu scende di otto piani, e la valle di Göreme è sparsa di camini di fata e chiese affrescate. Le mongolfiere partono alla prima alba — prenotate in anticipo. Succo d’arancia al volo, sevich del mercato, pesce al Bosforo — e il miglior rapporto prezzo-impressione della lista.'},
  t:{ru:['Шары — бронируйте на первый рассвет','Истамбулкарт — на весь транспорт','Померанцевый сок с улицы — обязательно'],
     en:['Balloon rides — book for the first sunrise','One Istanbulkart covers all the transport','A street-squeezed orange juice — mandatory'],
     it:['Le mongolfiere — prenotate per la prima alba','L’Istanbulkart copre tutto il trasporto','Il succo d’arancia spremuto in strada — obbligo morale']}},
 {i:'egypt',n:{ru:'Египет',en:'Egypt',it:'Egitto'},r:{ru:'Африка',en:'Africa',it:'Africa'},
  d:{ru:'Пирамиды и кораллы Красного моря.',en:'The pyramids and the corals of the Red Sea.',it:'Le piramidi e i coralli del Mar Rosso.'},
  s:{ru:'Египет — история в масштабе пирамид: у подножия Хеопса вы понимаете, что фотографии врут — они не передают размер. Пирамиды Гизы и Сфинкс — на утро; лучшее время для поездки — с октября по апрель, чтобы не плавиться. Луксор — музей под открытым небом: Карнак с колоннами по 23 метра и Долина царей, где стены расписаны красками, пережившими три тысячи лет; идите на рассвете, до жары и до групп. Абу-Симбел — отдельное чудо: в 1960-е храм Рамсеса II распилили на блоки и подняли выше уровня будущего водохранилища — инженерный подвиг рядом с архитектурным. Красное море — второй слой отпуска: кораллы в двух шагах от берега, маска и трубка с первого дня, дайвинг в Рас-Мохаммеде, где рыбы весят всеми цветами радуги. Чаевые «бакшиш» — держите мелочь наготове: это местный социальный инструмент, а не взятка. Композиция дня проще некуда: культура утром, коралловые рифы после обеда — такого сочетания нет больше нигде.',
     en:'Egypt is history at pyramid scale: at the foot of Khufu’s pyramid you understand that photographs lie — they cannot convey scale. The Giza pyramids and the Sphinx are for the morning; the best months run October to April — travel, do not melt. Luxor is a museum under open sky: Karnak with columns twenty-three metres tall, and the Valley of the Kings, where the walls keep colours that have outlived three thousand years; go at dawn, before heat and groups. Abu Simbel is a separate wonder: in the 1960s the temple of Ramesses II was cut into blocks and lifted above the future reservoir’s level — an engineering feat beside an architectural one. The Red Sea is the holiday’s second layer: corals a step from the shore, mask and snorkel from the first day, diving at Ras Mohammed, where the fish carry every colour of the rainbow. Baksheesh: keep small notes ready — a local social instrument, not a bribe. Monuments in the morning, coral reefs after lunch — no other country matches the pair.',
     it:'L’Egitto è storia in scala di piramide: ai piedi di Cheope capite che le foto mentono — non rendono la misura. Le piramidi di Giza e la Sfinge la mattina; meglio venire da ottobre ad aprile, per non sciogliersi. Luxor è un museo a cielo aperto: Karnak con colonne di 23 metri e la Valle dei Re, coi colori sopravvissuti a tremila anni; andate all’alba, prima della calura e dei gruppi. Abu Simbel è un miracolo a parte: negli anni Sessanta il tempio di Ramses II venne segato a blocchi e sollevato oltre il futuro livello del bacino — impresa d’ingegneria accanto a quella d’architettura. Il Mar Rosso è il secondo strato della vacanza: coralli a due passi dalla spiaggia, maschera e boccaglio dal primo giorno, immersioni a Ras Mohammed, coi pesci in tutti i colori dell’arcobaleno. Il baksheesh — tenete la moneta pronta: non è una mazzetta, è uno strumento sociale locale. La ricetta della giornata è semplice: cultura al mattino, coralli dopo pranzo — un abbinamento unico al mondo.'},
  t:{ru:['Красное море — маска и трубка с первого дня','Луксор — на рассвете, без жары','Чаевые «бакшиш» — держите мелочь'],
     en:['Red Sea — mask and snorkel from day one','Luxor at sunrise, before the heat','Baksheesh — keep small notes handy'],
     it:['Mar Rosso — maschera e boccaglio dal primo giorno','Luxor all’alba, senza calura','Baksheesh — tenete a portata la moneta']}},
 {i:'uae',n:{ru:'ОАЭ',en:'the UAE',it:'Emirati'},r:{ru:'Азия',en:'Asia',it:'Asia'},
  d:{ru:'Дубай будущего и пустынные сафари.',en:'Future Dubai and desert safaris.',it:'Dubai del futuro e safari nel deserto.'},
  s:{ru:'ОАЭ — город будущего посреди пустыни: Бурдж-Халифа в 828 метров, метро без водителей, сафари по дюнам и ужин в шатре под звёздами. Дубай работает как выставка: со смотровой Бурдж-Халифы видно, как залив встречает пустыню; билеты берите за три дня и на закат — свет в это время самый честный. Старый город — вторая глава: квартал Аль-Фахиди с ветряными башнями-бадгирами, деревянные лодки абра через залив за один дирхам, рынки золота и специй, где торгуются с улыбкой, а не с угрозой. Абу-Даби добавляет культуры: беломраморная мечеть шейха Зайда с 82 куполами и Лувр Абу-Даби, чей купол-решётка пропускает «дождь света» внутрь архитектуры — под ним хочется просто сидеть. Зимой тут +25 и солнце — фантастика без смены континента. Помните: пятница — короткий рабочий день, часть мест закрывается раньше; городские пляжи бесплатные и чистые, а пустыня ночью даёт вторую волну впечатлений.',
     en:'The UAE is a city of the future set in the desert: the Burj Khalifa at 828 metres, a driverless metro, safaris over the dunes and dinner in a tent under the stars. Dubai behaves like an exhibition: from the tower’s viewing deck you can see where the gulf meets the sand; take tickets three days ahead and for sunset, when the light is at its most honest. The old town is the second chapter: the Al Fahidi quarter with its wind towers, wooden abra boats crossing the creek for one dirham, and the gold and spice markets, where haggling comes with a smile, not a threat. Abu Dhabi adds culture: the white-marble Sheikh Zayed Mosque with its eighty-two domes, and the Louvre Abu Dhabi, whose latticed dome lets in a ‘rain of light’ — you simply want to sit beneath it. In winter it is +25 and sunny here: science fiction without changing continents. Friday is a short working day and some places close early; the city beaches are free and spotless, and the desert after dark delivers a second wave.',
     it:'Gli Emirati sono il futuro in mezzo al deserto: il Burj Khalifa di 828 metri, la metro senza conducente, safari sulle dune, cena in tenda sotto le stelle. Dubai funziona da mostra: dalla terrazza del Burj si vede il golfo che incontra il deserto; biglietti tre giorni avanti e al tramonto — luce a quell’ora la più onesta. La città vecchia è il secondo capitolo: il quartiere Al Fahidi con le torri-vento badgir, gli abra di legno che attraversano il golfo per un dirham, i mercati dell’oro e delle spezie, dove si contrattra col sorriso. Abu Dhabi aggiunge cultura: la moschea dello Sceicco Zayed, di marmo bianco con 82 cupole, e il Louvre Abu Dhabi, la cui cupola fa una «pioggia di luce» — sotto viene voglia di sedersi e non far altro. D’inverno qui ci sono +25 e sole — fantascienza, senza cambiare continente. Attenzione: il venerdì è un giorno lavorativo corto, alcuni posti chiudono prima; le spiagge urbane sono gratis e pulite, e il deserto la notte dà una seconda ondata di emozioni.'},
  t:{ru:['Бурдж-Халифа — билеты за 3 дня','Пятница в ОАЭ — короткий рабочий день: часть мест закрывается раньше','Пляжи городские — бесплатные и чистые'],
     en:['Burj Khalifa tickets — book 3 days ahead','Friday in the UAE is a short working day — some places close early','City beaches are free and spotless'],
     it:['Burj Khalifa — biglietti 3 giorni prima','Il venerdì negli Emirati è un giorno lavorativo corto: alcuni posti chiudono prima','Le spiagge urbane sono gratis e pulite']}},
 {i:'thailand',n:{ru:'Таиланд',en:'Thailand',it:'Thailandia'},r:{ru:'Азия',en:'Asia',it:'Asia'},
  d:{ru:'Острова, храмы и пляжи с книгой.',en:'Islands, temples and beaches with a book.',it:'Isole, templi e spiagge con un libro.'},
  s:{ru:'Таиланд — страна улыбок с конкретикой: храмы Бангкока, известняковые скалы Краби, длинные лодки к бирюзовым бухтам и уличная еда, за которую почти неловко платить так мало. Бангкок: храм Изумрудного Будды в комплексе королевского дворца, Ват-Арун на берегу реки — к закату, лодочные рынки рано утром и ночные рынки, где том-ям варят при вас. Краби — скалы, которые выныривают из моря прямёхонько к пляжам; Рейли добираться только на лодке — это часть удовольствия. Острова по настроению: Пхи-Пхи — на первой лодке утра, Ко-Ланта — для тишины, Самуи — классика с кокосами. Кухня — отдельная точка притяжения: пад-тай, том-ям, манго с липким рисом на десерт — и всё это дешевле третьего кофе в аэропорту. Практика простая: лонгтейл-лодку торгуйтесь на пристани, а не у отеля; ужин — на ночных рынках, вкусно и за копейки; массаж — в том же прейскуранте. Уезжаете отдохнувшим и полным планов вернуться: Таиланд не закрывается — он ждёт.',
     en:'Thailand is the land of smiles with specifics: the temples of Bangkok, Krabi’s limestone stacks, long-tail boats out to turquoise bays, and street food you feel embarrassed to pay so little for. In Bangkok: the Emerald Buddha temple in the Grand Palace, Wat Arun on the river, timed for sunset, floating markets at dawn and night markets where tom yum is cooked in front of you. Krabi means rocks that rise straight out of the sea towards the beaches; Railay is reachable only by boat — half the pleasure. The islands go by mood: Phi Phi on the first boat of the morning, Ko Lanta for quiet, Koh Samui — the classic, with coconuts. The cuisine is a destination in itself: pad thai, tom yum, mango with sticky rice — all cheaper than the third coffee at an airport. The practice is simple: haggle for the long-tail at the pier, not at the hotel; eat at the night markets for pennies; the massage comes at the same tariff. You leave rested and full of return plans: Thailand does not close — it waits.',
     it:'La Thailandia è il paese dei sorrisi, coi dettagli concreti: templi di Bangkok, scogliere di calcare di Krabi, barche long-tail verso baie turchesi e un cibo di strada quasi da vergognarsi a pagarlo così poco. Bangkok: il Buddha di Smeraldo nel Palazzo Reale, il Wat Arun al tramonto, i mercati galleggianti la mattina e quelli notturni, dove il tom yum si cuoce davanti a voi. Krabi — spuntoni che dal mare spuntano sulle spiagge; a Railay si arriva solo in barca — parte del piacere. Isole secondo umore: Phi Phi — sulla prima barca del mattino, Ko Lanta — la quiete, Samui — la classica col cocco. La cucina è un’attrazione a parte: pad thai, tom yum, mango col riso appiccicoso per dessert — tutto costa meno del terzo caffè d’aeroporto. La pratica: la long-tail si contratta alla banchina, non davanti all’hotel; la cena ai mercati notturni, buona e a pochi spicci; il massaggio allo stesso listino. Partite riposati e pieni di progetti di ritorno: la Thailandia non chiude — aspetta.'},
  t:{ru:['Лонгтейл-лодка — торгуйтесь на пристани','Остров Пхи-Пхи — лодка с утра','Ужин — на ночных рынках: вкусно и за копейки'],
     en:['Haggle for the long-tail boat right at the pier','Phi Phi — take the first boat out in the morning','Dinner at the night markets — excellent and cheap'],
     it:['La long-tail si contratta sulla banchina','Ko Phi Phi — la barca la mattina presto','La cena nei mercati notturni — golosa ed economica']}},
 {i:'indonesia',n:{ru:'Индонезия · Бали',en:'Indonesia · Bali',it:'Indonesia · Bali'},r:{ru:'Азия',en:'Asia',it:'Asia'},
  d:{ru:'Рисовые террасы, храмы, серфинг.',en:'Rice terraces, temples, surfing.',it:'Terrazze di riso, templi, surf.'},
  s:{ru:'Бали — остров тысячи храмов: террасы Тегалаланга, где слои риса спускаются ступеньками, как зелёная лестница к небу; водопады в джунглях; серфинг на закате и церемонии с лепестками на дороге — каждое утро местные выставляют маленькие корзинки кананг-сари, и улица на время становится храмом. Убуд — правильная база: кофейни с видом на джунгли, лес обезьян, мастерские батика и йога под цикад. Храм Улун-Дану-Бератан стоит прямо на озере и отражается так, будто парит; на входе выдают саронг — надевайте без разговоров, это часть уважения. Волны: Кута подойдёт новичкам, Улувату — тем, кто уже понимает, что делает; школа серфинга стоит дешевле ужина в Европе. Практика: скутер — только в шлеме и с правами, трафик живой; местная SIM-карта стоит копейки и решает интернет за весь отпуск. Идеален для перезагрузки: йога утром, рыба на гриле вечером, звёзды — без счёта: счёт тут ведут только цикады. Возвращаетесь другим человеком, тихо, но гарантированно.',
     en:'Bali is an island of a thousand temples: the Tegalalang terraces, where rice steps downhill like a green staircase; waterfalls deep in the jungle; surfing at sunset and ceremonies of petals along the road — every morning locals set out little canang-sari baskets, and for a while the street becomes a temple. Ubud is the right base: jungle-facing cafés, the monkey forest, batik workshops and yoga to a soundtrack of cicadas. The Ulun Danu Beratan temple stands on the lake as if floating; at the entrance you get a sarong — put it on; that is part of the respect. The waves: Kuta suits beginners, Uluwatu those who already know what they are doing; a surf school costs less than dinner in Europe. Practical notes: scooter only with a helmet and a licence, the traffic is very much alive; a local SIM costs pennies and settles the internet. A reset in full: yoga in the morning, grilled fish in the evening, stars beyond counting. You come back a slightly different person — quietly but reliably.',
     it:'Bali è l’isola dei mille templi: le terrazze di Tegalalang, dove gli strati di riso scendono a gradini come una scala verde; le cascate in giungla; il surf al tramonto e cerimonie coi petali sulla strada — ogni mattino i locali mettono le canang sari in mezzo alla via: per un istante la strada è un tempio. Ubud è la base: caffè con vista giungla, la foresta delle scimmie, botteghe di batik e yoga sotto le cicale. Il tempio di Ulun Danu Beratan sta sul lago e si riflette come se volasse; all’ingresso vi danno il sarong — mettetelo senza discutere: è rispetto. Le onde: Kuta ai principianti, Uluwatu a chi già sa cosa fa; la scuola di surf costa meno di una cena in Europa. La pratica: lo scooter solo col casco e la patente, il traffico è vivo; la SIM costa pochi centesimi e risolve la rete per la vacanza. Ideale per la ricarica: yoga al mattino, pesce alla brace la sera, stelle senza contatore — il conto lo tengono solo le cicale. Tornate un’altra persona: in silenzio, ma garantita.'},
  t:{ru:['Убуд — база для храмов и воды','Скутер — только в шлеме и с правами','Местная SIM-карта стоит копейки — интернет решён'],
     en:['Ubud is the base for temples and waterfalls','Scooters — helmet and licence only','A local SIM costs pennies and solves the internet'],
     it:['Ubud è la base per templi e cascate','Lo scooter — solo col casco e la patente','La SIM locale costa poco e risolve la connessione']}},
 {i:'japan',n:{ru:'Япония',en:'Japan',it:'Giappone'},r:{ru:'Азия',en:'Asia',it:'Asia'},
  d:{ru:'Сакура, Фудзи и поезда-пули.',en:'Cherry blossom, Fuji and bullet trains.',it:'Sakura, Fuji e treni proiettile.'},
  s:{ru:'Япония — контраст высшего пилотажа: неон Синдзюку против тишины храмов, синкансэн против чайной церемонии, и всё это работает одновременно, не мешая друг другу. Токио: Сибуя с переходом, виденным в каждом клипе, храм Мэйдзи в парке, где город внезапно затихает, и Асакуса вечером, когда бумажные фонари включают без причины — просто потому, что вечер. Киото — второй слой: Фусими-Инари с тысячами красных ворот, идущих в гору как лестница из открыток, Кинкаку-дзи — золотой павильон над озером, бамбуковая роща Арасияма, где стебли поют на ветру. Фудзи встаёт у окна синкансэна, если сесть на правильную сторону — места E, примерно три часа пути из Токио в Киото. Еда: суши у прилавка, рамен в переулке на шесть мест, омакасэ, где повар решает за вас — и решает лучше. Наличные держите наготове: храмы и мелкие лавки любят бумажник старой школы. Сакура цветёт в конце марта — бронируйте зимой. Каждый день что-то удивляет, и Япония никогда не делает это громко.',
     en:'Japan is contrast at expert level: the neon of Shinjuku against temple silence, the shinkansen against the tea ceremony — and it all runs at once, without quarrel. Tokyo: Shibuya and its crossing from every music video, the Meiji temple in a park where the city goes suddenly quiet, and Asakusa at night, when paper lanterns switch on for no reason — because it is evening. Kyoto is the second layer: Fushimi Inari with thousands of red gates climbing like a staircase of postcards, the golden pavilion of Kinkaku-ji above its lake, the Arashiyama bamboo grove where the stalks sing in the wind. Fuji stands at the train window if you take the right side — seat E, some three hours from Tokyo. Food: sushi at the counter, ramen in a six-seat alley, an omakase where the chef decides for you — and decides better. Keep cash handy: temples and small shops prefer it. Sakura blooms in late March — book in winter. Every day something surprises, and Japan never raises its voice doing it.',
     it:'Il Giappone è contrasto d’alta scuola: il neon di Shinjuku contro la quiete dei templi, lo shinkansen contro la cerimonia del tè — e tutto gira insieme, senza darsi fastidio. Tokyo: Shibuya con l’incrocio visto in ogni clip, il tempio Meiji nel parco dove la città abbassa la voce, e Asakusa la sera, quando le lanterne di carta si accendono — perché è sera. Kyoto: Fushimi Inari con migliaia di torii rossi che salgono in collina, scala di cartoline, il Kinkaku-ji — padiglione d’oro sul lago, il boschetto di bambù di Arashiyama, dove i fusti cantano col vento. Il Fuji sorge alla finestra dello shinkansen se prendete il lato giusto — i posti E, tre ore di viaggio da Tokyo. Cibo: sushi al banco, ramen nel vicolo da sei posti, omakase dove lo chef decide per voi — e decide meglio. Portate contanti: templi e botteghe piccole preferiscono il vecchio portafogli. La sakura fiorisce a fine marzo — prenotate d’inverno. Ogni giorno qualcosa stupisce, e il Giappone non lo fa mai a gran voce.'},
  t:{ru:['JR Pass — до прилёта, выгоднее','Наличные берите: храмы и мелкие лавки любят только их','Сакура — конец марта: бронируйте зимой'],
     en:['Buy the JR Pass before you land — it pays off','Carry cash: temples and small shops prefer it','Sakura peaks late March — book in winter'],
     it:['JR Pass prima dell’arrivo — conviene','Contante a portata: templi e piccoli negozi lo preferiscono','Sakura fine marzo — prenotate in inverno']}},
 {i:'iceland',n:{ru:'Исландия',en:'Iceland',it:'Islanda'},r:{ru:'Европа',en:'Europe',it:'Europa'},
  d:{ru:'Гейзеры, чёрные пляжи, голубая лагуна.',en:'Geysers, black beaches, the Blue Lagoon.',it:'Geyser, spiagge nere, la Blue Lagoon.'},
  s:{ru:'Исландия — планета в миниатюре: гейзер Строккур выстреливает каждые восемь минут по расписанию, которое он сам и устанавливает; Гулльфосс ревёт в каньоне; а тектонические плиты расходятся прямо у дороги — можно стоять одной ногой на Америке, другой на Европе. Золотое кольцо собирает три чуда за один день, Кольцевая дорога за восемь дней переписывает ваше представление о пейзаже: Сельяландсфосс, за который можно зайти за водяную стену; чёрный пляж Рейнисфьяра с колоннами из базальта; ледниковая лагуна Йёкюльсаурлоун, где айсберги плывут к морю неторопливо, как деловые письма. Гора Киркьюфелл — та самая, с открыток. Синяя лагуна — бронь заранее; одевайтесь слоями и следите за vedur.is: погода здесь меняется быстрее, чем вы выбираете объектив. Зимой — сияние: зелёные ленты ходят по небу, как занавес, который решили задернуть с изнанки. Уезжаете с новым пониманием слова «пейзаж» — и словарём для него.',
     en:'Iceland is a planet in miniature: the Strokkur geyser fires every eight minutes on a schedule it sets itself; Gullfoss roars in its canyon; and the tectonic plates drift apart right by the road — you can stand with one foot on America and one on Europe. The Golden Circle gathers three wonders into one day, and eight days on the Ring Road rewrite your idea of landscape: Seljalandsfoss, which you can walk behind like a water curtain; the basalt-black beach of Reynisfjara with its stone columns; the Jökulsárlón glacier lagoon, where icebergs drift towards the sea as unhurriedly as business letters. Mount Kirkjufell — that one, from the postcards. The Blue Lagoon — book ahead; dress in layers and follow vedur.is: the weather here changes faster than you can choose a lens. In winter comes the aurora: green ribbons cross the sky like a curtain pulled from the wrong side. You leave with a new understanding of the word landscape — and a vocabulary to match.',
     it:'L’Islanda è un pianeta in miniatura: il geyser Strokkur spara ogni otto minuti, con un orario che stabilisce da solo; il Gullfoss ruggisce nella gola; e le placche tettoniche si allontanano proprio lungo la strada — si può stare col piede in America e un altro in Europa. Il Cerchio d’Oro raccoglie tre miracoli in un giorno, e la Ring Road in otto riscrive la vostra idea di paesaggio: la Seljalandsfoss, dietro cui si passa oltre il muro d’acqua; la spiaggia nera di Reynisfjara con le colonne di basalto; la laguna glaciale di Jökulsarlon, dove gli iceberg vanno al mare con calma di biglietti commerciali. Il monte Kirkjufell è proprio quello delle cartoline. La Blue Lagoon va prenotata in anticipo; vestitevi a strati e seguite vedur.is: il tempo cambia più in fretta di quanto scegliiate l’obiettivo. D’inverno vi è l’aurora: le fasce verdi camminano nel cielo come un sipario tirato dalla parte sbagliata. Partite con un nuovo senso della parola «paesaggio» — e col vocabolario per usarlo.'},
  t:{ru:['Кольцевая дорога — аренда машины осенью','Синяя лагуна — бронь заранее','Погода меняется быстро: следите за vedur.is'],
     en:['The Ring Road — rent a car and go','Blue Lagoon — book ahead','The weather turns fast: follow vedur.is'],
     it:['Ring Road — prendete l’auto a noleggio','Blue Lagoon — prenotate in anticipo','Il meteo cambia in fretta: seguite vedur.is']}},
 {i:'belgium',n:{ru:'Бельгия',en:'Belgium',it:'Belgio'},r:{ru:'Европа',en:'Europe',it:'Europa'},s:{ru:'Бельгия — страна, которая не кричит о себе и потому всегда выигрывает. Брюгге — северная Венеция без пафоса: каналы, лебеди, три колокольни; приходите вечером после отъезда дневных групп — и город станет вашим. Утро — на лодке по каналам: с воды видно всё, что с земли скрыто за фасадами, а лодочник расскажет, где снимали «В Брюгге» и зачем башне 366 ступеней. Гент — второй акт и любимый сюжет художников: набережная Граслей вечером, когда зажигаются фонари, работает лучше любой галереи. Антверпен — для стиля: мода, алмазы и вокзал, который выглядит как дворец, потому что у него было время на репетиции. Гастрономия — отдельная страна: фритки с майонезом на рынке, вафли тёплыми с первого шага, шоколад по стилям и крепостям, и пиво — от ламбиков с вишней до тёмной квадрюпель из монастыря, где рецепт держат в тайне. Бельгийское пиво дегустируйте по стилям, а не по брендам — за одну неделю вы соберёте словарь вкусов, который останется с вами надолго.',
en:'Belgium is the country that never raises its voice, and that is exactly why it wins. Bruges is a northern Venice without the fuss: canals, swans, three bell towers; come in the evening, after the day trippers have gone, and the town is yours. The morning boat along the canals: from the water you see what the facades hide from the street, and the boatman will tell you where In Bruges was filmed and why the tower asks for 366 steps. Ghent is the second act and the painters’ favourite: the Graslei embankment at dusk, when the lamps come on, works better than any gallery. Antwerp is for style: fashion, diamonds and a station that looks like a palace, because it had time to rehearse. Food is a country of its own: frites with mayonnaise at the market, waffles warm from the first bite, chocolate by style and strength, and beer from cherry lambics to a dark quadrupel brewed behind monastery walls. Taste Belgian beer by style, not by brand — in one week you will build a vocabulary of flavours that stays with you.',
it:'Il Belgio è un paese che non alza la voce, e proprio per questo vince sempre. Bruges è la Venezia del nord senza posa: canali, cigni, tre campanili; arrivate la sera, quando i pullman se ne vanno, e la città diventa vostra. La mattina prendete la barca sui canali: dall’acqua si vede ciò che le facciate nascondono, e il barcaiolo vi dirà dove hanno girato In Bruges e perché la torre ha 366 gradini. Gand è il secondo atto e il soggetto preferito dei pittori: la Graslei la sera, quando si accendono i lampioni, funziona meglio di una galleria d’arte. Anversa è lo stile: moda, diamanti e una stazione che sembra un palazzo, perché ha avuto tempo per le prove. La gastronomia è un paese a parte: fritte con maionese al mercato, gaufres tiepide dal primo passo, cioccolato per stili e gradi, e birra — dalle lambic alla ciliegia alla quadrupel scura di un monastero che tiene segreta la ricetta. Assaggiate la birra belga per stili, non per marchi: in una settimana costruirete un vocabolario di sapori che resterà con voi.'},
  t:{ru:['Брюгге — вечером, после отъезда групп','Фри́тки — на рынке, не в фастфуде','Пиво — дегустируйте по стилям'],
     en:['Bruges after the day trippers leave','Frites at the market, not fast food','Taste beer by style, not brand'],
     it:['Bruges la sera, dopo i gruppi','Frites al mercato, non al fast food','La birra assaporata per stile']}},
 {i:'hungary',n:{ru:'Венгрия',en:'Hungary',it:'Ungheria'},r:{ru:'Европа',en:'Europe',it:'Europa'},s:{ru:'Венгрия — термальный отпуск с культурой в комплекте. Будапешт правильнее всего раскрывается с воды: вечерний круиз по Дунаю мимо подсвеченного Парламента — и вы понимаете, зачем город строили именно здесь, на обоих берегах. Купальни Сечени работают и зимой: пар над снегом, шахматисты в воде, и всё это — ритуал, к которому местные имеют пожизненный абонемент. Смотровая на Рыбацком бастионе даёт лучший вид на реку и мосты, а Кофе А́лександра внутри — как билет в другое столетие. Прогулка по Пешту складывается сама: проспект Андраши, Опера, площади с каштанами и кондитерские, где торт Dobos режут на глазах. Буда берёт холмами: крепость, лабиринт, виды. Вне столицы — изогнутое озеро Балатон с виноградниками северного берега и городки, которые пахнут ланошем, а также Токай: сладкое асу — вино, которое по закону собирается вручную, ягода за ягодой. Венгерская кухня честная и сытная: гуляш в котле, лангош с чесноком и паприка в том количестве, которое вы себе определите сами.',
en:'Hungary is a thermal holiday with culture thrown in. Budapest opens best from the water: an evening cruise along the Danube past the lit-up Parliament, and you understand why the city was built here, on both banks. The Széchenyi baths work in winter too: steam above the snow, chess players waist-deep in the water — a ritual locals hold lifetime passes to. The Fisherman’s Bastion gives you the best view of the river and the bridges, and the café inside feels like a ticket to another century. On the Pest side the walk assembles itself: Andrássy Avenue, the Opera, chestnut-lined squares and confectioneries where Dobos torte is sliced in front of you. Buda takes the hills: the castle, the views. Beyond the capital there is the curved Lake Balaton with vineyards on its northern shore, towns that smell of lángos, and Tokaj: the sweet aszú is picked by hand, berry by berry, as the law requires. Hungarian food is honest and filling: goulash from a cauldron, lángos with garlic, and paprika in whatever quantity you dare.',
it:'Ungheria: vacanza termale con la cultura in dotazione. Budapest si capisce meglio dall’acqua: la crociera serale sul Danubio davanti al Parlamento illuminato vi spiega perché la città è nata proprio qui, su due rive. Le terme Széchenyi funzionano anche d’inverno: vapore sopra la neve, scacchi in acqua — e tutto questo è un rito a cui i locali hanno l’abbonamento a vita. Dal Bastione dei Pescatori avete la vista migliore sul fiume e sui ponti, e il caffè Alexander è un biglietto per un altro secolo. La parte di Pest si cammina da sola: l’Andrássy út, l’Opera, piazze con castagni e pasticcerie dove tagliano il Dobos davanti ai vostri occhi. Buda chiede salita: fortezza, labirinto, panorami. Fuori dalla capitale, il lago Balaton con i vigneti della riva nord e i paesini che profumano di lángos, e Tokaj: l’aszú dolce è un vino che per legge si raccoglie a mano, grappolo per grappolo. La cucina ungherese è onesta e abbondante: gulasch nel paiolo, lángos all’aglio e paprika nella dose che decidete voi.'},
  t:{ru:['Сечени зимой — пар над снегом','Дунай — лучше с воды вечером','Токайское асу пробуйте смело: это сладко по правилам'],
     en:['Széchenyi in winter — steam over snow','See the Danube from the water, in the evening','Try Tokaji Aszú bravely — sweetness by law'],
     it:['Széchenyi d’inverno: vapore sulla neve','Il Danubio si guarda dall’acqua, la sera','Tokaji Aszú: dolce secondo le regole']}},
 {i:'czech',n:{ru:'Чехия',en:'Czechia',it:'Repubblica Ceca'},r:{ru:'Европа',en:'Europe',it:'Europa'},s:{ru:'Прага — город, который выглядит как декорация и живёт как обычная столица, и это сочетание и есть её секрет. Карлов мост идите на рассвете: тридцать статуй, туман над Влтавой и никого — через час всё это станет аттракционом, а вы успеете раньше. Староместская площадь работает по расписанию астрономических часов: толпа собирается к часу: вы встречаете куранты, а затем уходите в Йозефов — еврейский квартал с кладбищем, где камни стоят друг на друге поколениями. Пиво в Праге — гражданское право: кружка пльзеньского у стены в шинке дешевле воды, а смиховские вари с солодовым профилем объясняют, почему чехи пьют больше всех и при этом ходят по горам без одышки. За городом — Кутна-Хора с костницей, украшенной костями сорока тысяч человек: мрачная, но честная история, и Чешский Крумлов — город-петля на излучине Влтавы. Кухня простая и честная: свичкова с кнедликами — главное здесь кнедлики, которые работают как губка для соуса. Прага награждает тех, кто встанет рано.',
en:'Prague looks like a film set and lives like an ordinary capital, and this combination is its secret. Walk Charles Bridge at sunrise: thirty statues, mist over the Vltava and nobody there — within the hour it all becomes an attraction, and you will have been first. The Old Town Square runs on the astronomical clock’s schedule: the crowd gathers for the hour, you watch the show, then slip away into Josefov, the Jewish Quarter with a cemetery where the stones stacked over generations. Beer in Prague is a civil right: a pilsner in a neighbourhood hospoda costs less than water, and the malty Smíchov brews explain why Czechs drink the most in Europe and still walk mountains without losing breath. Out of town: Kutná Hora with a bone church decorated by the skeletons of forty thousand people — morbid, but an honest story — and Český Krumlov, a town curled into a loop of the Vltava. The food is honest: svíčková with dumplings, the dumplings like a sponge for the sauce. Prague rewards whoever gets up early.',
it:'Praga sembra un set e vive come una capitale qualunque, e in questo sta il suo segreto. Il Ponte Carlo andateci all’alba: trenta statue, nebbia sulla Moldava e nessuno — un’ora dopo tutto diventa un luna-park, e voi ci arrivarete prima. La piazza della Città Vecchia si guarda secondo l’orologio astronomico: aspettate lo scoccare dell’ora, poi si va a Josefov — il quartiere ebraico, con il cimitero dove le lapidi si reggono generazione dopo generazione. A Praga la birra è un diritto: un boccale di pilsner alla parete in una hospoda costa meno dell’acqua, e le birre di Smíchov col profilo di malto spiegano perché i cechi bevono più di tutti e poi salgono in montagna senza fiato. Fuori città: Kutná Hora con la cappella delle ossa, decorata con i resti di quarantamila persone — macabra ma onesta — e Český Krumlov, il borgo a ricciolo sulla svolta della Moldava. Cucina semplice e sincera: svíčková coi knedlíky — e sono i knedlíky la cosa seria, perché assorbono il sugo come spugne. Praga premia chi si alza presto.'},
  t:{ru:['Карлов мост — на рассвете','Часы на Староместской площади — к началу часа','Пиво в шинке дешевле воды — это норма'],
     en:['Charles Bridge at sunrise','The Old Town clock — at the top of the hour','Beer cheaper than water — that is normal'],
     it:['Ponte Carlo all’alba','L’orologio astronomico all’inizio dell’ora','La birra costa meno dell’acqua: è normale']}},
 {i:'poland',n:{ru:'Польша',en:'Poland',it:'Polonia'},r:{ru:'Европа',en:'Europe',it:'Europa'},s:{ru:'Краков — учебник по истории, который читается легко. Рыночная площадь — крупнейшая в средневековой Европе: суконные ряды посередине, голуби, трубач с башни, который обрывает мелодию на непонятной ноте — так звучит легенда про стрелу в горло. Вавель с драконом внизу, Казимеж — еврейский квартал с пекарнями, где заблудиться приятнее, чем в музее. Соляная шахта Величка — отдельная страна: три километра вниз, часовня, вырезанная из соли, с люстрами из соли, и соль в воздухе, от которой перехватывает дыхание. Дальше — Освенцим — рядом, и это не для соцсетей: час тишины, который ценнее любого музея. Кухня: pączki с розовым вареньем, бигос и żurek в хлебной буханке. Цены дружелюбные, поезда чистые, а суббота заканчивается не позднее вечера — чешётся план на весну: Гданьск с янтарём, Вроцлав с гномами на углах. Краков за выходные покажет вам Польшу целиком — а Польша того стоит.',
en:'Kraków is a history textbook that reads easily. The Main Market Square is the largest medieval square in Europe: the Cloth Hall in the middle, pigeons, and a trumpeter on the tower who cuts the melody mid-note — that is the legend of the arrow in his throat. Wawel keeps its dragon down below; Kazimierz, the old Jewish quarter, keeps synagogues and bakeries where it is nicer to get lost than in a museum. The Wieliczka salt mine is a separate country: three kilometres down, a chapel carved from salt with chandeliers of salt, and brine lakes that mirror everything — the salt holds its breath along with you. Then there is Auschwitz, close by, and not for social media: an hour of silence worth more than any museum. Food: pączki with rose jam on Thursday, like the locals, bigos, and żurek served in a bread loaf. Prices are friendly and the trains are clean. Kraków will show you the whole of Poland in a weekend — and Poland is worth it.',
it:'Cracovia è un manuale di storia che si legge di corsa. La piazza del Mercato è la più grande dell’Europa medievale: i Sukiennice in mezzo, i piccioni, il trombettiere della torre che tronca la melodia su una nota inaspettata — così suona la leggenda della freccia in gola. Wawel col drago in fondo, e Kazimierz, il quartiere ebraico con le sinagoghe e i forni, dove perdersi è più piacevole che al museo. La miniera di sale di Wieliczka è un paese a parte: tre chilometri in giù, una cappella intagliata nel sale, lampadari di sale e laghi di salamoia che riflettono tutto — il sale vi tiene il respiro. Poi Auschwitz, vicino: non è roba per i social, è un’ora di silenzio che vale più di qualunque museo. Cucina: pączki con la marmellata di rose, bigos, żurek servito nella pagnotta, e in chiusura una birra alla frutta. I prezzi sono garbati, i treni puliti. Cracovia in un weekend vi racconta la Polonia intera — e la Polonia merita il viaggio.'},
  t:{ru:['Величка — бронируйте спуск утром','Пончики с розой — в четверг, как местные','Освенцим — закладывайте полдня и тишину'],
     en:['Wieliczka — book the morning descent','Pączki with rose jam on Thursday, like locals','Auschwitz — budget half a day and silence'],
     it:['Wieliczka: la discesa al mattino','Pączki alla rosa il giovedì, come i locali','Auschwitz: mezza giornata e silenzio']}},
 {i:'denmark',n:{ru:'Дания',en:'Denmark',it:'Danimarca'},r:{ru:'Европа',en:'Europe',it:'Europa'},s:{ru:'Дания — это хюгге в национальном масштабе: страна, где счастье измеряют в свечах и кашеминовых пледах. Копенгаген начинается с Нюхавна — гавани с разноцветными домами, в которых жил сказочник Андерсен; теперь здесь кофе лучше, чем в сказках. Парк Тиволи в центре города работает с 1843 года: старые качели, иллюминация и духовой оркестр — ностальгия в промышленных масштабах. Велосипеды здесь — основной транспорт, и вы за день привыкнете к тому, что три возраста и две собаки едут рядом с вами по выделенной дорожке. Свободный город Христиания — отдельная республика с флагами и правилами; заходите с открытыми глазами, но без телефона в руке. Музеи хорошие: корабли викингов в Роскилле — настоящие корпуса, под которых вы просунете голову с уважением. Кухня: смёрребред на ржаном, открытые сэндвичи как малые картины, и кондитерские с булочками с корицей, свежими с утра. Вечером — сауна на пирсе с заходом прямо в гавань, если наберётесь смелости.',
en:'Denmark is hygge on a national scale: a country that measures happiness in candles and cashmere blankets. Copenhagen begins at Nyhavn, the harbour of coloured houses where the storyteller Andersen once lived; the coffee there is now better than the fairy tales. Tivoli, in the very centre, has been running since 1843: old carousels, thousands of lights and a brass band — nostalgia in industrial volumes. Bicycles are the main transport here, and within a day you will be used to sharing the cycle lane with three generations and two dogs. Freetown Christiania is a separate republic with its own flags and rules; walk in with your eyes open and the phone in your pocket. The museums hold up: the Viking ships at Roskilde are real hulls, and you will duck under them with respect. Food: smørrebrød on rye, open sandwiches arranged like small paintings, and bakeries with cinnamon swirls fresh from the morning batch. In the evening, a sauna on the pier with a jump straight into the harbour, if you dare.',
it:'La Danimarca è il hygge su scala nazionale: un paese dove la felicità si misura in candele e plaid di cachemire. Copenaghen comincia dal Nyhavn — il porticciolo delle casette colorate dove abitava il favolista Andersen; oggi il caffè è migliore delle favole. Il Tivoli funziona dal 1843: giostre d’epoca, luminarie, banda — la nostalgia in scala industriale. Qui la bicicletta è il mezzo principale, e in un giorno vi abituerete a pedalare fianco a fianco con tre generazioni e due cani sulla pista riservata. Christiania è una repubblica a parte, con bandiere e regole proprie: entrate a occhi aperti, ma a telefono spento. I musei tengono: le navi vichinghe di Roskilde, veri scafi in cui infilerete la testa con rispetto. Cucina: smørrebrød sul pane di segale, tramezzini aperti come piccole tele, e brioches alla cannella profumate dal mattino. La sera, sauna sul pontile con discesa direttamente nella baia — se avete il coraggio.'},
  t:{ru:['Тиволи — вечером, на подсветке','Велосипед напрокат — и вы местный за час','Смёрребред заказывайте набор — попробуете сразу пять'],
     en:['Tivoli at night, under the lights','Rent a bike — you are local within an hour','Order the smørrebrød platter — five at once'],
     it:['Tivoli la sera, con le luci','Bicicletta a noleggio: locali in un’ora','Il piatto di smørrebrød: cinque insieme']}},
 {i:'sweden',n:{ru:'Швеция',en:'Sweden',it:'Svezia'},r:{ru:'Европа',en:'Europe',it:'Europa'},s:{ru:'Швеция держит баланс: столица на четырнадцати островах, тишина в тридцати тысячах островов дальше и дизайн во всём, включая вывески. Стокгольм начинается с Гамла-стан — старого города с улицами шириной в плечо и черепицей, красной, как шведский дом в детском альбоме. Музей корабля «Васа» — отдельное чудо: в XVII в. корабль утонул через километр после спуска на воду и пролежал три века в холодной воде без жучка — оттого вы видите его целым, с резьбой на каждом бимсе. Дроттнингхольм — «шведский Версаль» за час пути на пароме, который здесь считается общественным транспортом. Архипелаг — второй день: электричка-катер уходит в волны каждые полчаса, и на любом острове вы найдёте красный домик, скалы с соснами и тишину, за которую в других местах платят аренду. Фика — кофейная пауза с булочкой и корицей, здесь не традиция, а трудовое право: присоединяйтесь дважды в день. Зимой — полярное сияние за полярным кругом: поезда ходят, а небо иногда танцует.',
en:'Sweden keeps its balance: a capital on fourteen islands, silence on thirty thousand more further out, and design in everything, including the street signs. Stockholm starts with Gamla Stan, the old town with streets a shoulders’ width wide and roof tiles as red as the Swedish house in a children’s book. The Vasa museum is a wonder of its own: in the seventeenth century the ship sank a kilometre into her maiden voyage and lay three centuries in cold water — no woodworm, so you see her whole, with carving on every beam. Drottningholm is the Swedish Versailles, an hour away by ferry, which here counts as public transport. Day two is the archipelago: a ferry-tram sets off into the waves every half-hour, and on any island you will find a red cottage, rocks with pines and the kind of silence other places charge rent for. Fika — a coffee pause with a cinnamon bun — is not a tradition but labour law: join in twice a day. In winter the aurora waits beyond the polar circle: the trains run, and the sky sometimes dances.',
it:'La Svezia tiene il bilancio: una capitale su quattordici isole, trentamila isole di silenzio poco più in là e un design ovunque, insegne comprese. Stoccolma comincia da Gamla stan, la città vecchia con strade larghe quanto due spalle e tetti rossi come la casetta svedese dell’album dei bambini. Il museo del Vasa è un miracolo: nel Seicento la nave affondò a un chilometro dal varo e trascorse tre secoli in acqua fredda, senza un tarlo — ecco perché la vedete intera, con l’intaglio su ogni trave. Drottningholm è il «Versailles svedese», a un’ora di ferry che qui conta come linea urbana. Il secondo giro è per l’arcipelago: il battello parte ogni mezz’ora, e su un’isola qualunque troverete casetta rossa, scogli con pini e un silenzio per cui altrove si paga un affitto. La fika — pausa caffè con brioche alla cannella — qui non è una tradizione: è un diritto di lavoro. Partecipate due volte al giorno. In inverno, l’aurora boreale oltre il circolo polare: i treni sono regolari, e il cielo ogni tanto balla.'},
  t:{ru:['«Васа» — на открытие, без групп','На остров архипелага — первой катер-электричкой','Фика — дважды в день, это закон'],
     en:['Vasa Museum right at opening','Catch the first ferry-tram to an island','Fika twice a day — it is the law'],
     it:['Il museo Vasa all’apertura','Primo battello-tram per un’isola','La fika due volte al giorno: è legge']}},
 {i:'finland',n:{ru:'Финляндия',en:'Finland',it:'Finlandia'},r:{ru:'Европа',en:'Europe',it:'Europa'},s:{ru:'Финляндия — страна, где тишина — вид ресурса, и она возобновляемая. Хельсинки компактный и честный: кафедральный собор на лестнице, район Суоменлинна — морская крепость на четырёх островах, до которой паром идёт пятнадцать минут и стоит меньше билета в метро. Финская сауна — не спа, а гражданство: общественные сауны работают по вечерам, после бассейна с прорубью; окунание входит в программу добровольно-обязательно. Дизайн-квартал: Marimekko с полосатыми чашками, Iittala со стеклом, и всё это в пешей доступности от кофе с коричным пайком. Зимняя Финляндия — отдельная глава: Лапландия со снегоходами, хаски и оленьими фермами, где Санта принимает по расписанию, а сияние — по погоде. Летом — озёрный край: Сайма, в которой сто тысяч озёр растворяются друг в друге, и коттеджи на сваях, где вы наконец прочитаете ту книгу. Финский характер совпадает с климатом: прямолинейный, тёплый внутри и не тратящий слов впустую. Отдых здесь получается глубоким.',
en:'Finland is a country where silence is a listed resource, and a renewable one. Helsinki is compact and honest: the cathedral up its wide steps, and Suomenlinna, a sea fortress spread over four islands, fifteen minutes away by a ferry that costs less than a metro ticket. The Finnish sauna is not a spa treatment, it is a citizenship: public saunas open in the evenings, and the dip into cold water afterwards is part of the programme — compulsory-optional. The Design District runs from striped Marimekko mugs to Iittala glass, all within walking distance of coffee and a cinnamon pastry. Winter Finland is its own chapter: Lapland with snowmobiles, husky rides and reindeer farms where Santa keeps office hours and the aurora follows the weather. In summer comes the lake district: on Saimaa a hundred thousand lakes dissolve into one another, and in cottages on stilts you finally read that book. The Finnish character matches the climate: direct, warm underneath and unwilling to waste words. Holidays here come out deep.',
it:'La Finlandia è un paese dove il silenzio è risorsa — ed è rinnovabile. Helsinki è compatta e sincera: il Duomo in cima alla scalinata, la fortezza di mare Suomenlinna su quattro isole, a quindici minuti di traghetto che costa meno di un biglietto della metro. La sauna finlandese non è spa: è politica di cittadinanza. Le saune pubbliche la sera si riempiono, e il tuffo nel buco nel ghiaccio è la parte del programma facoltativa-obbligatoria. Il quartiere del design: le tazze a strisce di Marimekko, il vetro Iittala, tutto a due passi dal caffè con una dose extra di cannella. La Finlandia invernale è un capitolo separato: Lapponia con motoslitte, husky e allevamenti di renne, un Babbo Natale in servizio regolare e le aurore, secondo il meteo. D’estate, il lago Saimaa: centomila laghi che si sciolgono uno nell’altro, e cottage su palafitte dove finalmente leggerete quel libro. Il carattere finlandese somiglia al clima: diretto, caldo dentro, contrario allo spreco di parole. Il riposo qui arriva fino in fondo.'},
  t:{ru:['Общественная сауна — вечером, с окунанием','Суоменлинна — на пароме, не на экскурсии','В Лапландии — снегоход и хаски в один день'],
     en:['Public sauna in the evening, dip included','Take the ferry to Suomenlinna, not a tour','In Lapland: snowmobile and huskies in one day'],
     it:['Sauna pubblica la sera, con il tuffo','Suomenlinna col traghetto, non con il tour','In Lapponia: motoslitta e husky in un giorno']}},
 {i:'slovenia',n:{ru:'Словения',en:'Slovenia',it:'Slovenia'},r:{ru:'Европа',en:'Europe',it:'Europa'},s:{ru:'Словения — компактный альбом: горы, озеро и море укладываются в одну неделю дорог. Блед — открытка, которая работает вживую: остров с церковью посреди озера, лодки гребут к острову, а на колокольне — колокол желаний — по легенде, желание сработает, если позвонить искренне. Замок над озером стоит на скале и смотрит на озеро сверху. Постойнская пещера — пять километров подземной Европы: поезд везёт вас внутрь, как в фильм о подземном городе, а сталактиты растут с такой уверенностью, будто им тут комфортно. Любляна — столица размером с район Москвы: драконий мост, старый город, замок на холме и пекарни, где пахнет потицей — праздничным рулетом с орехами. На море — Пиран в венецианском камне и солеварни Сечовлье, где соль собирают так, как собирали при Венецианской республике. Вина — терan из Карста, красное с привкусом железа, как и положено землям над пещерами. Словения не шумит — и именно поэтому запоминается целиком.',
en:'Slovenia is a compact album: mountains, a lake and the sea all fit into one week of easy driving. Lake Bled is a postcard that works in real life: an island church in the middle of the water, reached by wooden boats, and a wish bell on the belfry — ring it sincerely, legend says, and the wish holds. The castle above the lake stands on a cliff and looks down on everything. The Postojna cave is five kilometres of underground Europe: a train carries you inside as if into a film about an underground city, and the stalactites grow with the confidence of long-term tenants. Ljubljana is a capital the size of one district: the Dragon Bridge, an old town, a castle on the hill and bakeries smelling of potica, the festive walnut roll. On the coast Piran keeps its Venetian stone, and at the Sečovlje salt pans salt is still gathered as it was under the Venetian Republic. The wine is karst-made: red Teran with an iron tang, as befits the land above the caves. Slovenia does not make noise — which is why it sticks in the memory.',
it:'La Slovenia è un album compatto: montagne, lago e mare in una settimana di strade. Il Bled è una cartolina che funziona anche dal vivo: l’isola con la chiesa nel mezzo, dove si arriva in barca, e la campana dei desideri sul campanile — la leggenda dice che se la suonate con sincerità, il desiderio si realizza. Il castello, su una roccia, guarda dall’alto. La grotta di Postumia è cinque chilometri di Europa sotterranea: il trenino vi conduce dentro come in un film, e le stalattiti crescono con una sicurezza che dà pace. Lubiana è una capitale in dimensioni da quartiere: ponte dei draghi, città vecchia, castello sul colle e panetterie che profumano di potica, la treccia festiva alle noci. Sul mare, Piran in pietra veneziana e le saline di Sečovlje, dove il sale si raccoglie come ai tempi della Repubblica di Venezia. Nei bicchieri, il teran del Carso: rosso con un fondo di ferro, come si conviene alle terre sopra le grotte. La Slovenia non fa rumore — e proprio per questo resta nella memoria.'},
  t:{ru:['Блед — позвоните в колокол желания','Постойна — внутри поезд, одевайтесь теплее','Теран из Карста — красное, к местным колбасам'],
     en:['Bled: ring the wish bell','Postojna has a train inside — dress warm','Try the red Teran from the Karst with sausages'],
     it:['Bled: suonare la campana dei desideri','Postumia: dentro c’è un treno, vestitevi caldi','Il Teran del Carso rosso, con le salsicce']}},
 {i:'montenegro',n:{ru:'Черногория',en:'Montenegro',it:'Montenegro'},r:{ru:'Европа',en:'Europe',it:'Europa'},s:{ru:'Черногория влезает в один кадр и не мешает себе: бухта Котор — «самый южный фьорд Европы», где горы сходятся в воду отвесно, а город внутри колец крепостных стен лежит как в ладони. Котор: старый город с улицей в один аршин шириной, кошки на каждом подоконнике и крепость Св. Ивана — 1400 ступеней вверх; на вершине дыхание сбивается дважды: от подъёма и от вида. Пераст — за ленивое утро: два рукотворных острова, один из которых насыпан из камней кораблей. Выезд серпантином на Ловчен — перпендикулярные повороты с видом на страну целиком: горы, бухта, Адриатика в дымке. Будва даёт пляжи и рынки со спелыми гранатами; Свети-Стефан выглядит так, что вы поверите любому рассказу о его венецианском прошлом. Еда — морская: устрицы в бухте, рыба на гриле, вино из автохтонных сортов вранац и крстац. Сезон мягкий: в октябре вода ещё тёплая, а бары — свободные.',
en:'Montenegro fits into one frame and does not get in its own way: the Bay of Kotor, Europe’s southernmost fjord, where mountains drop straight into the sea and the town rests inside the rings of fortress walls like something in a cupped hand. Kotor: an old town with lanes a hand’s width wide, a cat on every windowsill, and the fortress of St John — 1,400 steps up; the climb takes your breath twice, once on the stairs and once at the view. Perast is for a lazy morning: two man-made islands, one of them built up stone by stone from ships. The serpentine road to Lovćen turns at right angles and hands you the whole country at once: mountains, the bay, the Adriatic in a haze. Budva supplies beaches and markets with ripe pomegranates, and Sveti Stefan looks so good you will believe any story about its Venetian past. Food comes from the sea: oysters in the bay, grilled fish, and wine from the local Vranac and Krstač grapes. The season is gentle: in October the water is still warm and the bars are free.',
it:'Il Montenegro sta intero in una foto e non si mette d’impaccio. La baia di Kotor è «il fiordo più a sud di Europa»: le montagne scendono a picco sull’acqua e la città dentro gli anelli delle mura si stende come in un palmo di mano. A Kotor: la città vecchia con vicoli larghi quanto un braccio, gatti su ogni davanzale e la fortezza di San Giovanni — 1400 gradini in su, e in cima il respiro si perde due volte: per la salita e per la vista. Perast è per una mattina pigra: due isole artificiali, l’una nata dalle pietre portate dalle navi. La serpentina che sale a Lovćen gira a strapiombo, ma vi regala il paese intero: monti, baia, Adriatico nella foschia. Budva porta spiagge e mercati con granate e fichi, e Sveti Stefan è talmente scenografico che ci crederete a qualsiasi racconto sul suo passato veneziano. Cucina di mare: ostriche nella baia, pesce alla griglia, i vini autoctoni vrmač e krstač. La stagione è mite: in ottobre l’acqua è ancora calda e i bar sono vostri.'},
  t:{ru:['Крепость Котора — 1400 ступеней к 8 утра','Серпантин Ловчена — с остановками на виды','Устрицы в бухте — свежее всего на утро'],
     en:['Kotor fortress: 1400 steps by 8 am','The Lovćen serpentine — stop for every view','Oysters are freshest in the morning'],
     it:['La fortezza di Kotor: 1400 gradini entro le 8','La serpentina del Lovćen, con sosta a ogni panoramica','Le ostriche sono fresche al mattino']}},
 {i:'malta',n:{ru:'Мальта',en:'Malta',it:'Malta'},r:{ru:'Европа',en:'Europe',it:'Europa'},s:{ru:'Мальта — архипелаг размером с один хороший отпуск: три острова, семь тысяч лет истории и свет, от которого камень светится медово. Валлетта строилась рыцарями как крепость-шахматная доска: одна длинная улица, перпендикуляры, балконы с закрытыми ставнями — и вид на две гавани, где лодки пестрят, как на параде. Собор св. Иоанна снаружи суров, внутри — золочёный барокко, у которого нет конкурентов на квадратный метр. Мальтийский камень — тёплый на ощупь: дома здесь режут из известняка, как хлеб. Выезды простые: Голубой грот на утренней воде, рыболовные лодки в Марсашлокке с глазами на носу, Мдина — «тихая столица» на высоте, где вечером слышно собственные шаги. Комино — Голубая лагуна: вода цвета стекла на солнце. Кухня — тёплая средиземноморская с британским акцентом: паштицци с горошком, рагу из кролика в воскресенье и фтира с тунцом. Двуязычие наизусть: мальтийский и английский — понятно без словаря.',
en:'Malta is an archipelago sized to one good holiday: three islands, seven thousand years of history and a light that turns the stone to honey. Valletta was built by the knights as a fortress chessboard: one long street, right angles, balconies with closed shutters — and a view over two harbours where the boats parade in every colour. St John’s Co-Cathedral is stern outside and, inside, gilded Baroque with no rival per square metre. Maltese limestone is warm to the touch: houses here are cut from it like bread. The outings are simple: the Blue Grotto on the morning water, fishing boats at Marsaxlokk with eyes painted on the bows, and Mdina, the silent capital up on its height, where in the evening you can hear your own footsteps. Comino brings the Blue Lagoon: water the colour of glass held up to the sun. The food is warm Mediterranean with a British accent: pastizzi with peas, rabbit stew on Sunday, ftira with tuna. The Maltese are bilingual by default — Maltese and English — so you will manage without a phrasebook.',
it:'Malta è un arcipelago grande quanto un buon soggiorno: tre isole, settemila anni di storia e una luce che fa diventare la pietra miele. La Valletta fu costruita dai cavalieri come una fortezza-scacchiera: una lunga via principale, perpendicolari, balconi con le persiane chiuse — e il colpo d’occhio su due porti, dove le barche colorate sfilano come a una parata. La concattedrale di San Giovanni si mostra severa da fuori e, da dentro, un barocco dorato senza rivali al metro quadrato. La pietra maltese è calda al tatto: qui le case si tagliano nel calcare. Le gite sono facili: il Blu Grotto sull’acqua del mattino, le luzzu da pesca di Marsaxlokk con gli occhi dipinti a prua, Mdina — la «città silenziosa» in alto, dove la sera si sentono i vostri passi. Comino è la Laguna Blu: acqua come vetro al sole. Cucina — mediterranea calda con accento britannico: pastizci con i piselli, stufato di coniglio la domenica e ftira col tonno. I maltesi portano a memoria il bilinguismo — maltese e inglese: a voi non servirà altro.'},
  t:{ru:['Голубой грот — до десяти утра','Мдина — вечером, когда город слышен','Паштицци — ешьте стоя у пекарни'],
     en:['The Blue Grotto before 10 am','Mdina at night — when you can hear the city','Eat pastizzi standing at the bakery'],
     it:['Il Gruppo Azzurro prima delle 10','Mdina la sera, quando la città si sente','Pastizzi in piedi davanti al forno']}},
 {i:'morocco',n:{ru:'Марокко',en:'Morocco',it:'Marocco'},r:{ru:'Африка',en:'Africa',it:'Africa'},s:{ru:'Марокко работает на всех пяти чувствах сразу и не обещает порядок — обещает интенсивность. Марракеш: площадь Джама-эль-Фна к вечеру превращается в театр под открытым небом — сказочники, змееводы, пары от жаровен и апельсиновый сок за монету. Медина — лабиринт, в котором вы заблудитесь, и это лучший вид навигации: пятна цвета, лавки с коврами, стук молотков по меди. Шопинг с торгом — часть игры: начинайте с трети, улыбайтесь, и чай с мятой принесут сами. Дальше — Атлас: перевал Тизи-н-Тишка, снег в горах, оазисы внизу; Айт-Бен-Хаддоу — глина и солнце (снимали «Гладиатора» и половину приключенческих фильмов). Фес — старая медина без машин и осёл с мешками; кожевенники в красочных чанах — вид с террасы, запах — с ветра. дюны Эрг-Шебби: ночь в кемпе под дюной, звёзды без счёта и рассвет, ради которого встают без будильника. Кухня: тажин с бараниной и черносливом, хлеб из общественной печи. Марокко остаётся в одежде — пыль цвета терракоты, — и вы будете рады.',
en:'Morocco works on all five senses at once and promises intensity, not order. Marrakech: by evening Jamaa el-Fna turns into an open-air theatre — storytellers, snake charmers, smoke from the grills and orange juice for a coin. The medina is a labyrinth you will get lost in — the best navigation there is: bursts of colour, shops stacked with carpets, the knock of hammers on copper. Haggling is part of the game: start at a third, smile, and the mint tea arrives on its own. Then the Atlas: the Tizi n’Tichka pass, snow above, oases below; Ait Benhaddou, clay and sun — Gladiator and half the adventure films were shot here. Fes keeps a car-free old medina; the tannery’s dye pits look like a palette from the terrace, and the smell arrives with the wind. In the desert spend the night, not just an evening: a camp under the dunes of Erg Chebbi, stars beyond counting, a sunrise worth waking for. Tajine with lamb and prunes, bread from the shared oven — Morocco stays on your clothes as terracotta dust, and you will be glad.',
it:'Il Marocco lavora su tutti i sensi insieme e non promette ordine: promette intensità. Marrakech: Jemaa el-Fna la sera diventa un teatro all’aperto — contastorie, incantatori di serpenti, fumo dei fornelli, aranciate a una monetina il bicchiere. La medina è un labirinto in cui vi perderete, ed è il miglior navigatore possibile: tessuti di ogni colore, banchi di tappeti, martelli sul rame. Contrattare è gioco: partite da un terzo del prezzo, sorridete, e il thè alla menta arriverà da solo. Poi l’Atlante: il passo Tizi n’Tichka, la neve sui monti e le oasi in fondo; Ait Benhaddou è argilla e sole — lì hanno girato Gladiator. Fez: la medina vecchia senza auto, l’asinello con i sacchi, i conciatori nelle vasche colorate: si guardano dal terrazzo, il profumo arriva col vento. Sull’Erg Chebbi: notte in campo sotto la duna, stelle senza numero e un’alba per cui ci si sveglia senza sveglia. Cucina: tagine d’agnello alle prugne, pane dal forno comune. Il Marocco resta addosso, terra color terracotta — e vi farete piacere.'},
  t:{ru:['Медина — с гидом, а торговаться самим','В пустыне — ночь в кемпе, а не вечер','Тажин — с бараниной и черносливом, проверено'],
     en:['Take a guide in the medina; haggle on your own','In the desert: a night in camp, not just an evening','Tajine with lamb and prunes — trust us'],
     it:['Nella medina con la guida; il mercato è affare vostro','Nel deserto: una notte in campo, non solo la sera','Tajine con agnello e prugne: fidatevi']}},
 {i:'jordan',n:{ru:'Иордания',en:'Jordan',it:'Giordania'},r:{ru:'Азия',en:'Asia',it:'Asia'},s:{ru:'Иордания собирает три мира на одну карту и одну неделю. Петра — сокровищница набатаев, вырезанная в розовом песчанике: вы идёте сквозь каньон Сик шириной в плечо, скалы сходятся сверху, и вдруг между стенами — фасад сокровищницы, от которого перехватывает дыхание. Jordan Pass — виза и билеты одной покупкой, экономика честная. В Петре ходите дальше сокровищницы — к монастыру Ад-Дейр наверх и к королевским гробницам: большинство разворачивается раньше. Вади-Рум — «марсианский» песок и силуэты гор, по которым Т.Э. Лоуренс водил верблюдов без GPS; ночь в бедуинском кемпе: огонь, хлеб на углях с заатаром, звёзды без счёта и дюны, которые молчат так убедительно. Мёртвое море — финал: вы плаваете, сидя в воде, как в кресле, соль держит, как кресло; грязь с берега — обязательная программа. Еда — левантийское золото: хумус, мутаббаль, маклуба и лимонад с мятой. Страна заканчивается быстрее, чем вы к ней привыкаете.',
en:'Jordan folds three worlds into one map and one week. Petra, the Nabataeans’ treasure cut into rose-red sandstone: you walk the Siq, a canyon a shoulders’ width wide, the rock closing high overhead, and suddenly between the walls the Treasury facade appears and takes the breath clean away. Take the Jordan Pass — visa and entry tickets in one receipt, honest arithmetic. In Petra keep going past the Treasury, up to the Monastery and the royal tombs: most people turn back earlier. Wadi Rum is Martian sand and mountain silhouettes that T. E. Lawrence once crossed with camels and no GPS; a night in a Bedouin camp means a fire, bread baked in the embers, stars beyond counting and dunes that argue for silence better than any words. The Dead Sea is the finale: you float sitting in the water as in an armchair, the salt holds you politely, and the mud from the shore is compulsory fun. Food is Levantine gold: hummus, mutabbal, maqluba and lemonade with mint. The country ends sooner than you get used to it.',
it:'La Giordania mette tre mondi in una mappa e in una settimana. Petra, il tesoro dei nabatei, scavato nell’arenaria rosa: attraversate il Siq, la gola larga quanto una spalla, le pareti si chiudono in alto — e tra le pareti sbuca la facciata del Tesoro, da cui vi si trattiene il fiato. Prendete il Jordan Pass: visto e biglietti inclusi, l’economia del viaggio è onesta. In Petra andate oltre il Tesoro — al Monastero Ad-Deir, in alto, e alle tombe reali: la maggior parte dei turisti gira i talloni prima. Wadi Rum: sabbia marziana e le sagome dei monti su cui Lawrence di Arabia guidava i cammelli senza GPS; la notte nel campo beduino: fuoco, pane sui carboni, stelle senza numero e dune che fanno un silenzio molto persuasivo. Il Mar Morto chiude in bellezza: si nuota da seduti, come in una poltrona — il sale vi tiene bene, e il fango dalla riva è una parte del programma. In tavola, l’oro levantino: hummus, mutabbal, maqluba e limonata alla menta. La Giordania finisce prima che voi vi ci abituiate.'},
  t:{ru:['Jordan Pass — виза и билеты одним чеком','Петра — идите к монастырю, большинство нет','Мёртвое море — берите сандалии для воды'],
     en:['Jordan Pass: visa and tickets in one receipt','Stay in Petra past the Treasury — most turn back','Water sandals for the Dead Sea — the salt bites'],
     it:['Jordan Pass: visto e biglietti in un’unica ricevuta','Oltre il Tesoro di Petra: la maggioranza si ferma','Sandali d’acqua per il Mar Morto: il sale morde']}},
 {i:'india',n:{ru:'Индия',en:'India',it:'India'},r:{ru:'Азия',en:'Asia',it:'Asia'},s:{ru:'Индия не прощает полумеры — и награждает тех, кто пришёл целиком. Тадж-Махал на рассвете: белый мрамор розовеет, туман над Ямуной, и вы понимаете, зачем шах Джахан потратил двадцать два года на любовь, которую можно строить. Агра — первый кадр; второй — Джайпур, розовый город с Хава-Махал, где окон больше, чем жителей, и фортом Амбер в горах. Дели задаёт ритм: старый город, мечеть Джама-Масджид, рынок специй, где перец пахнет цветом. Керала — третий темп: хаусбот — дом-лодка на каналах, креветки на кокосе, рисовые поля ниже уровня воды и тишина, за которую вы платите не деньгами, а темпом. Гоа — свои пляжи, южные спокойнее северных. Кухня — вселенная: тали на банановом листе, масала-доса на завтрак, чаи с гор Дарджилинга. Практика: еда там, где очередь местных; вода — только бутилированная. Индия меняет вас сильнее, чем вы её.',
en:'India forgives nothing half-done — and rewards whoever arrives all the way in. The Taj Mahal at sunrise: the white marble blushes, mist lies on the Yamuna, and you understand why Shah Jahan spent twenty-two years on a love you can build. Agra is the first frame; the second is Jaipur, the pink city, with Hawa Mahal and its windows-by-the-hundred, and Amber Fort up in the hills. Delhi sets the rhythm: the old city, the Jama Masjid mosque, a spice market where pepper smells like colour. Kerala is the third tempo: a houseboat drifting the backwater canals, prawns with coconut, rice paddies below the waterline, and silence you pay for not in money but in pace. Goa has its own beaches — the south calmer than the north. The food is a universe: thali served on a banana leaf, masala dosa for breakfast, teas from the Darjeeling hills. Practical notes: eat street food where the local queue is, and drink bottled water only. India changes you more than you change it.',
it:'L’India non perdona le mezze misure: premia chi arriva per intero. Il Taj Mahal all’alba: il marmo bianco rosseggia, la nebbia sullo Yamuna, e capite perché lo scià Jahan ha speso ventidue anni su un amore che si può costruire. Agra è il primo fotogramma; il secondo è Jaipur, la città rosa, con l’Hawa Mahal, dove le finestre sono più degli abitanti, e il forte Amber in collina. Delhi detta il ritmo: città vecchia, la moschea Jama Masjid, il mercato delle spezie, dove il pepe profuma di colore. La Kerala va al terzo tempo: una houseboat lungo i canali, gamberi al cocco, risaie sotto il livello dell’acqua e un silenzio che non si paga in soldi: si paga in ritmo. Le spiagge di Goa: al sud più tranquille di quelle al nord. La cucina è un universo: thali in foglia di banana, masala dosa per colazione, thè dei monti Darjeeling. In pratica: mangiate là dove coda la gente del posto, e solo acqua in bottiglia. L’India vi cambia più in fretta di quanto cambiate voi lei.'},
  t:{ru:['Тадж-Махал — к открытию, на рассвете','Еда там, где очередь местных','Джайпур в розовом камне смотрится до полудня'],
     en:['The Taj at sunrise, right at opening','Eat where the locals queue','Jaipur’s pink stone reads best before noon'],
     it:['Taj Mahal all’alba, all’apertura','Mangiate dove fanno la fila i locali','Jaipur rosa si legge prima di mezzogiorno']}},
 {i:'vietnam',n:{ru:'Вьетнам',en:'Vietnam',it:'Vietnam'},r:{ru:'Азия',en:'Asia',it:'Asia'},s:{ru:'Вьетнам — страна, которая работает на контрасте скорости и спокойствия. Халонг-бей: три тысячи известняковых островов над заливом, ночёвка на джонке, каяки в утреннем тумане и пещеры, в которых капитан выключает свет — не пугайтесь, это финал экскурсии. Хойан — город фонарей: янтарная старая часть, когда-то шумный порт, и вечер, когда город выключает электричество и включает бумажные светильники; лодка с лампами — обязательная программа. Сапа и север — рисовые террасы по склонам гор, где ступени идут за горизонт, и хмонги в индиго продают хендмейд без навязчивости. Кухня — главный магнит: фо с утренним паром, бун-ча с ханойского запаха угля, бан-ми с багетом, который остался с французов и стал полностью вьетнамским. Кофе — со сгущёнкой и льдом, медленный и крепкий. Пляжи — Дананг на мостах и море, Фукуок — островная тишина. Вьетнам ест, ездит на скутерах и улыбается одновременно — попробуйте в этом порядке.',
en:'Vietnam runs on the contrast of speed and calm. Ha Long Bay: three thousand limestone islands standing in green water, a night aboard a junk, kayaks in the morning fog and caves where the captain switches off the light — do not worry, that is the finale of the tour. Hội An is the city of lanterns: an amber old quarter that was once a busy port, and an evening when the town switches off the electricity and lights its paper lamps instead; the boat with candles is part of the programme. Sapa and the north: rice terraces climbing the mountainsides, steps running past the horizon, and Hmong in indigo selling handicrafts without pestering anyone. The food is the main magnet: phở with its morning steam, bún chả with the coal smoke of Hanoi, bánh mì — a baguette left by the French that went fully Vietnamese. Coffee comes with condensed milk and ice, slow and strong. Beaches: Da Nang with its bridges and sea, Phu Quoc for island quiet. Vietnam eats, rides a scooter and smiles all at the same time — try it, in that order.',
it:'Il Vietnam lavora al contrasto fra corsa e calma. La baia di Ha Long: tremila isole calcaree su un golfo, la notte su una jonca, canoa nella nebbia del mattino e grotte in cui il capitano spegne la luce — non spaventatevi: è il finale della gita. Hội An è la città delle lanterne: la parte antica color ambra, un tempo porto molto vivo, e la sera, quando la città spegne la corrente e accende i lampadari di carta; la barca con le lampade è d’obbligo. Sa Pa e il nord: terrazze di riso sui pendii, dove i gradini salgono oltre l’orizzonte, e gli Hmong in indaco vendono l’artigianato senza insistere. La cucina è il magnete principale: phở al vapore del mattino, bún chả all’odore di carbonella di Hanoi, bánh mì col baguette lasciato dai francesi e ormai tutto vietnamita. Il caffè: con latte condensato e ghiaccio, lento e forte. Le spiagge: Da Nang tra monti e mare, Phu Quốc — tregua insulare. Il Vietnam mangia, guida lo scooter e sorride contemporaneamente — provate in quest’ordine.'},
  t:{ru:['Халонг — с ночёвкой на джонке','Хойан — вечером, на бумажных фонарях','Кофе со сгущёнкой — медленно, как местные'],
     en:['Ha Long: sleep aboard a junk','Hội An after dark, in paper lanterns','Coffee with condensed milk — slowly, like locals'],
     it:['Ha Long: dormite sulla giunca','Hội An dopo il tramonto, coi lanternai di carta','Caffè col latte condensato: piano, come i locali']}},
 {i:'singapore',n:{ru:'Сингапур',en:'Singapore',it:'Singapore'},r:{ru:'Азия',en:'Asia',it:'Asia'},s:{ru:'Сингапур — город, который доказывает, что фантастика может быть аккуратной. Сады у бухты: супердеревья высотой с двадцатиэтажку, которые вечером проводят музыкальное шоу света, и два купола — цветочный и облачный лес, где температура искусственно держится на уровне гор. Марина-Бэй-Сэндс с кораблём на трёх башнях — смотровая на 57-м: лучший вечерний ракурс на залив и на город, который любит порядок. Хокер-центры — гастрономический парадокс: лапша за три доллара с мишленовским рейтингом, чили-краб, и всеядные очереди, где бухгалтер и таксист едят рядом. Зоопарк ночной — животные не притворяются, что ночуют, а выходят на смену; речной сафари с пандами — держите план утра. Культурные слои настоящие: Чайна-таун, Маленькая Индия, мечеть Султана в кампонг-гламе. Практика: город дорогой на алкоголь и щедрый на метро, зонт — не только от дождя, но и от солнца. планируйте три дня: город мал, но плотный, как хороший эспрессо.',
en:'Singapore proves that fantasy can be tidy. Gardens by the Bay: supertrees as tall as a twenty-storey block that run a light-and-music show after dark, and two domes — a flower dome and a cloud forest kept artificially mountain-cool. Marina Bay Sands, the ship resting across three towers, has an observation deck on the 57th floor: the best evening angle on the bay and on a city that loves order. Hawker centres are the gastronomic paradox: noodles for three dollars with a Michelin citation, chilli crab on a proper plate, and omnivorous queues where an accountant and a taxi driver eat side by side. The night safari means animals that actually clock in after dark; the river park with its pandas belongs to the morning plan. The cultural layers are real: Chinatown, Little India, the Sultan mosque in Kampong Glam. Practically: the city is expensive on alcohol and generous on the metro, and an umbrella serves against the sun as much as against the rain. Plan three days: the city is small but dense, like a good espresso.',
it:'Singapore dimostra che la fantascienza può essere in ordine. I Gardens by the Bay: supertrees alte venti piani, che la sera mettono in scena uno show di luci, e due cupoli — quello dei fiori e la foresta nuvolosa — dove il clima è artificialmente quello dei monti. Marina Bay Sands, con la nave sulle tre torri: al 57° piano c’è la terrazza, l’angolo serale migliore sul golfo e su una città che ama l’ordine. Gli hawker centres sono un paradosso gastronomico: ramen a tre dollari con valutazione Michelin, chili crab sul piatto — non sulla carta — e code dove contabile e tassista mangiano gomito a gomito. Lo zoo notturno è sincerissimo: gli animali non fanno finta di dormire, escono in servizio; i panda del River Safari — teneteli per la mattinata. Strati culturali veri: Chinatown, Little India, la moschea del Sultano al Kampong Glam. In pratica: qui l’alcol è caro e la metropolitana è generosa; l’ombrellino serve per pioggia e per sole. Fatevi tre giorni: la città è piccola ma densa, come un buono espresso.'},
  t:{ru:['Супердеревья — вечером, на шоу света','Хокер-центр — ешьте, где очередь из местных','Зонт днём — от солнца, не только от дождя'],
     en:['Supertrees after dark, at the light show','Eat at hawker stalls with a local queue','An umbrella by day — for the sun, not just rain'],
     it:['I Supertrees la sera, allo spettacolo di luce','Mangiate al centro hawker con la fila dei locali','L’ombrello di giorno vale per il sole']}},
 {i:'maldives',n:{ru:'Мальдивы',en:'the Maldives',it:'Maldive'},r:{ru:'Азия',en:'Asia',it:'Asia'},s:{ru:'Мальдивы — двадцать шесть атоллов, на которых вы наконец выясните, как выглядит слово «горизонт», если убрать всё остальное. Вода здесь бывает трёх цветов в один день: бирюза утром, сапфир в полдень и стекло к закату. Вилла над водой со стеклянным полом — не про показуху, а про то, что под вами живёт целый риф: рыбы учат вашу таблицу цветов заново. Сноркелинг с домашнего рифа — без лодок и групп; манты приходят по сезону, черепахи — по настроению, и оба пункта входят без доплат. Закатная рыбалка: местные удят с деревянной катушки, ловится лучше у тех, кто не торопится. дони — водное такси архипелага: с одного атолла на другой — как на автобусе, только под вами кораллы. Питание — рыбный и кокосовый: тунец с местным чили, кокос в каждом десерте. Локальные острова (Тулусду) — дешевле курортов и честнее: те же волны и вода, цена ниже, культура — живая. Телефон на неделю можно выключить: горизонт работает сам.',
en:'The Maldives are twenty-six atolls where you learn what the word horizon looks like once everything else is removed. The water runs through three colours in a single day: turquoise in the morning, sapphire at noon, glass by sunset. An over-water villa with a glass floor is not about showing off — the reef lives right under you and re-teaches your colour chart. Snorkelling starts at the house reef: no boats, no groups; mantas arrive in season, turtles by mood, and neither costs extra. Sunset fishing: the locals cast from a hand line, and the catch goes to whoever is in no hurry. The dhoni, a wooden boat, is the archipelago’s water taxi — from one atoll to the next like a bus, only with coral underneath. The food is fish and coconut: tuna with local chilli, and coconut in every dessert. Local islands such as Maafushi or Thulusdhoo are cheaper and more honest than the resorts: the same waves and water, a lower bill and a living culture. You can switch your phone off for the week — the horizon works on its own.',
it:'Le Maldive sono ventisei atolli dove finalmente scoprite com’è fatto l’orizzonte, se togliete tutto il resto. Qui l’acqua in un giorno ha tre colori: turchese al mattino, zaffiro a mezzogiorno, vetro al tramonto. La villa sull’acqua col pavimento di vetro non è sfoggio: sotto di voi vive una barriera intera — i pesci vi faranno riscoprire la tavola dei colori. Lo snorkelling parte dalla barriera di casa, senza barche né gruppi; le manta arrivano per stagione, le tartarughe per umore — e niente supplementi. La pesca al tramonto: i locali alzano la lenza col mulinello di legno; beato chi non ha fretta. Il dhoni è il taxi d’acqua dell’arcipelago: da un atollo all’altro come in autobus, solo con i coralli sotto di voi. In tavola è pesce e cocco: tonno col peperoncino del luogo, cocco in ogni dolce. Le isole locali (Maafushi, Thulusdhoo) costano meno dei resort e sono più oneste: stesse onde, stessa acqua, prezzo più basso, cultura viva. Il telefono potete tenerlo spento una settimana: l’orizzonte lavora da solo.'},
  t:{ru:['Домашний риф — снорклинг каждый день','Локальные острова — дешевле и честнее','Солнце экватора — фактор 50 и повторно'],
     en:['Snorkel the house reef daily','Local islands — cheaper and more honest','Equatorial sun: SPF 50, and reapply'],
     it:['Lo snorkel sul reef di casa ogni giorno','Isole locali: più economiche e più vere','Sole all’equatore: fattore 50 e riapplicare']}},
 {i:'sri-lanka',n:{ru:'Шри-Ланка',en:'Sri Lanka',it:'Sri Lanka'},r:{ru:'Азия',en:'Asia',it:'Asia'},s:{ru:'Шри-Ланка — цейлонский чай, слоны и пляжи, уложенные в остров размером с область. Горная Шри-Ланка: поезд Канди—Элла идёт сквозь чайные плантации, девятиарочный мост Nine Arch Bridge встаёт из джунглей как каменное кружево, и все выходят фотографировать — и правильно делают. Хапутале и Нувара-Элия — плантации на высоте, где чай собирают вручную женщины-сборщицы, а дегустация на фабрике объясняет разницу между высокогорьем и долиной. Культура: скала Сигирия — дворец на монолит, подняться 1200 ступеней к утру, к фрескам «девам облаков»; храм зуба Будды в Канди — вечерняя церемония с барабанами. слоновий питомник Пиннавела и сафари в Яле — леопарды на деревьях, если повезёт. Пляжи: юг — Мира и Арун-бей с серф-школой дешевле европейской, Тринкомали — восток с спокойной водой. Кухня: рис и карри с десяти тарелок, хопперы на завтрак и чай с джагери (jaggery). Люди улыбаются легко — вы будете улыбаться чаще.',
en:'Sri Lanka packs Ceylon tea, elephants and beaches into an island the size of one region. In the hill country the Kandy–Ella train runs through the tea plantations, the Nine Arch Bridge rises out of the jungle like lace in stone, and everyone gets out to photograph it — rightly so. Haputale and Nuwara Eliya sit at plantation altitude: the pickers work the rows by hand, and a factory tasting explains the difference between highland and valley leaf. Culture: Sigiriya, a palace on a monolith — climb the 1,200 steps in the morning, before the heat, for the cloud maiden frescoes; in Kandy, the Temple of the Tooth holds an evening ceremony with drums. The elephant orphanage at Pinnawala and a safari in Yala — leopards in the trees, if you are lucky. Beaches: the south with Mirissa and a surf school cheaper than Europe’s, Trincomalee on the east coast with calm water. Food: rice and curry with ten small dishes, hoppers for breakfast, tea with jaggery instead of sugar. People smile easily here — you will smile more often.',
it:'Lo Sri Lanka: thè di Ceylon, elefanti e spiagge, tutto in un’isola grande quanto una regione. I monti: il treno Kandy–Ella attraversa le piantagioni di thè, il ponte a nove archi sorge dalla giungla come un pizzo di pietra: tutti scendono a fotografarlo, e fanno bene. Haputale e Nuwara Eliya: piantagioni in quota, dove il thè si raccoglie a mano, e la degustazione in fabbrica vi spiega la differenza fra alte colline e valle. La cultura: la roccia di Sigiriya, un palazzo su monolite — salite i 1200 gradini, fino agli affreschi delle «signore delle nuvole»; il Tempio del Dente a Kandy vi aspetta con la cerimonia serale e i tamburi. Pinnawala, il rifugio degli elefanti, e il safari nello Yala: leopardi sugli alberi, se la fortuna aiuta. Le spiagge: al sud Mirissa e Arugam Bay con il surf che in Europa costa il doppio, Trincomalee a est con l’acqua più calma. Cucina: riso e curry in dieci scodelle, hoppers a colazione e thè con jaggery. Le persone sorridono con facilità — e vi ritroverete a sorridere più spesso.'},
  t:{ru:['Поезд Канди—Элла — второй класс с открытыми окнами','Сигирия — к утру, до жары','Джаггери вместо сахара'],
     en:['Kandy–Ella train: 2nd class, windows open','Sigiriya early, before the heat','Jaggery instead of sugar in your tea'],
     it:['Treno Kandy—Ella: 2ª classe, finestre aperte','Sigiriya presto, prima del caldo','Lo jaggery al tè, non lo zucchero']}},
 {i:'china',n:{ru:'Китай',en:'China',it:'Cina'},r:{ru:'Азия',en:'Asia',it:'Asia'},s:{ru:'Китай — страна, которая масштабирует всё, включая ваше воображение о «далеко». Великая стена: участок Мутянью — зелёные хребты, канатка наверх и стена, уходящая в дым, сколько видит глаз; приходите утром — толпы подтянут к полудню. Пекин — Запретный город по центральной оси, где красные стены отрастают в бесконечность, хутун — старые переулки, где жизнь идёт на лавочках, и утка по-пекински в тонких лепёшках, по которой вы будете мерить все остальные утки. Шанхай — парад небоскрёбов Пудуна с набережной Бунд напротив: колониальные фасады смотрят на будущее через реку, и вечером оба города включаются как сцена. Лапша ламянь руками — вытягивается на ваших глазах в два метра и в бульон; димсамы по утрам, тележки со стеллажами проезжают между столами. Ханчжоу с Западным озером: лотосы, мосты и поэтические названия, которые здесь дают даже камешкам. Мобильный платёж здесь работает быстрее, чем ваша кредитка, — подготовьте приложение заранее. Китай не показывает всё сразу — он показывает по регионам, как сериал.',
en:'China scales everything, including your idea of the word far. The Great Wall at Mutianyu: green ridges, a cableway to the top and a wall walking off into the haze as far as the eye holds; come in the morning — the crowds arrive by noon. Beijing is the Forbidden City along its central axis, where the red walls run towards infinity, the hutong lanes, where life goes on at little street tables, and Peking duck in thin pancakes — the measure of all other ducks. Shanghai pairs the skyscraper parade of Pudong with the Bund across the river: colonial facades facing the future, and in the evening both banks light up like a stage set. Hand-pulled lamian stretches to two metres before you and lands in the broth; dim sum in Guangzhou rolls past on morning trolleys. Hangzhou brings West Lake: lotus, bridges and poetic names even for the pebbles. Mobile payment here runs faster than your credit card — set the app up before the trip. China never shows you everything at once; it shows you one region at a time, like a series.',
it:'La Cina scala tutto, perfino la vostra idea del «lontano». La Grande Muraglia: la sezione di Mutianyu — colline verdi, la funivia in cima e un muraglio che svanisce nella foschia oltre lo sguardo; venite presto, le folle da mezzogiorno. Pechino: la Città Proibita lungo l’asse, dove le mura rosse sembrano infinite; gli hutong, dove la vita va su una panca, e l’anatra di Pechino nella sottile tortina — da qui in poi misurerete le altre anatre. Shanghai: la parata dei grattacieli di Pudong contro il Bund — le facciate coloniali guardano il futuro attraverso il fiume; la sera le due rive si accendono come una scena. La pasta tirata a mano si allunga davanti a voi sino a due metri e finisce nel brodo; i dim sum per colazione, portati dai carrelli in sala. A Hangzhou, il lago dell’Ovest: loto, ponti e toponimi poetici, dati perfino alle pietruzzine. Il pagamento col cellulare qui funziona più in fretta della carta: preparate l’app prima di partire. La Cina non mostra tutto insieme: si mostra a capitoli, come una serie.'},
  t:{ru:['Мутянью — по будням, к 9 утра','Приложение платежей — до поездки','Утка по-пекински — с лепёшками и огурцом'],
     en:['Mutianyu on a weekday, by 9 am','Set up a payments app before the trip','Peking duck: with pancakes and cucumber'],
     it:['Mutianyu nei feriali, entro le 9','L’app di pagamento prima della partenza','Anatra la Pechino: con pancake e cetriolo']}},
 {i:'south-korea',n:{ru:'Южная Корея',en:'South Korea',it:'Corea del Sud'},r:{ru:'Азия',en:'Asia',it:'Asia'},s:{ru:'Южная Корея — страна, где традиция и неон живут в одной на одной лестнице. Сеул: дворец Кёнбоккун к открытию — на смену караула, и туристы в арендованных ханбоках, которым вход бесплатный, выглядят честнее, чем звучит. Букчон — квартал ханок-домов: черепичные крыши между небоскрёбами, каменные стены и пекарни, запахи которых заставляют спуститься с горы. Горы — внутри города: гора Инвангсан с рассветными пробежками, башенки из камней-желаний на скалах. Рыбный рынок Норянджин: кальмар живой, осьминог — по-корейски честный. Кухня: к-барбекю с углями в столе, кимчи в каждом приёме, бингсу (bingsu) со льдом и манго; кофейни — отдельная вселенная, включая те, что стоят прямо на горах. Ночной Сеул — Донгдэмун: шопинг до рассвета. Страна работает как батарейка: кофейни на горах, ритуалы в городе, и возвращаются сюда чаще, чем планируют.',
en:'South Korea is a country where tradition and neon live on the same staircase. Seoul: Gyeongbokgung palace at opening, with the guard change on the hour, and tourists in rented hanbok who enter for free — it sounds touristy and works. Bukchon is the quarter of hanok houses: tiled roofs folded in between skyscrapers, stone walls and bakeries whose smell alone takes you back down the hill. The mountains sit inside the city: Inwangsan with its dawn runners and little towers of wish stones stacked on the rocks. Noryangjin fish market: live squid, octopus prepared the honest Korean way. The food: K-BBQ with the coals set into the table, kimchi at every meal, bingsu — shaved ice with mango for dessert — and cafés as a universe of their own, including ones planted straight on the mountainsides. Night Seoul means Dongdaemun: shopping until dawn. The country works like a battery — plug in and recharge. And with a T-money card the metro runs frictionless while you do.',
it:'La Corea del Sud è un paese dove la tradizione e il neon vivono nello stesso edificio. Seul: il palazzo Gyeongbokgung all’apertura — col cambio della guardia, e i turisti in hanbok a noleggio, che entrano gratis: è più grazioso di come suona. Bukchon è il quartiere delle case hanok: tetti di tegole tra i grattacieli, muri di pietra e un profumo di pane appena sfornato che vi farà scendere la collina. La montagna è dentro la città: l’Inwangsan con le corse all’alba e i desideri ammucchiati in torretine sulle rocce. Il mercato del pesce Noryangjin: il calamaro vivo, il polpo alla maniera coreana, senza reticenze. In tavola: K-BBQ con i carboni sul tavolo, kimchi in ogni pasto, bingsu con ghiaccio e mango; le caffetterie sono un universo a parte, comprese quelle in cima ai monti. Seul notturna: Dongdaemun — lo shopping fino all’alba. Il paese funziona come una batteria: collegatevi e ricaricatevi.'},
  t:{ru:['Ханбок напрокат — и вход в дворец бесплатный','К-барбекю — заказывайте не меньше двух видов мяса','Метро без пробок — держите T-money карту'],
     en:['Rent a hanbok — palace entry is free','K-BBQ: order at least two kinds of meat','A T-money card keeps the metro frictionless'],
     it:['Hanbok a noleggio: ingresso al palazzo gratis','K-BBQ: almeno due tipi di carne','La T-money rende la metro fluida']}},
 {i:'mexico',n:{ru:'Мексика',en:'Mexico',it:'Messico'},r:{ru:'Америка',en:'America',it:'America'},s:{ru:'Мексика — страна слоёв: майя внизу, колониальные фасады сверху и уличная еда посередине всего. Юкатан: Чичен-Ица к открытию — пирамида Кукулькана и звук эха, который майя настраивали нарочно; сеноты — воронки с бирюзовой водой в известняке: купаетесь в геологии, свет падает сверху столбом. Мерида — белый колониальный город с салбутес, тако с яйцом и тыквенными семечками, и вечерами на площадях — сальса. Оахака — гастрономическая столица: моль негро, тамале в банановых листьях, мескаль с апельсином и солью gusano, как положено. Пуэбла — керамика Талавера. Пляжи — Тулум с руинами на клифе и остров Женщин с тихой водой. Кухня — такос al pastor на каждом углу и не бойтесь острого — вы научитесь. Приветствуют легко и часто: мексиканская вежливость — это климат, а не протокол. Отдых здесь получается вкусным в буквальном смысле.',
en:'Mexico is a country of layers: the Maya at the bottom, colonial facades above, and street food in the middle of everything. On the Yucatán: Chichén Itzá at opening — the pyramid of Kukulcán and an echo the Maya tuned on purpose; the cenotes are sinkholes of turquoise water set into the limestone, so you swim inside geology with a column of light falling from above. Mérida is a whitewashed colonial city with salbutes — tacos with egg and pumpkin seeds — and salsa playing on the squares in the evenings. Oaxaca is the gastronomic capital: black mole, tamales in banana leaves, and mezcal with orange and worm salt, taken as traditionally as it sounds. Puebla adds its Talavera ceramics to the list. The beaches: Tulum with ruins standing right on the cliff, and Isla Mujeres with quiet water. The cuisine is tacos al pastor on every corner — and do not fear the chilli, you will learn. People greet you easily and often, and the holiday comes out delicious in the most literal sense.',
it:'Il Messico è un paese a strati: in fondo i maya, sopra le facciate coloniali, e nel mezzo, dappertutto, il cibo di strada. Lo Yucatán: Chichén Itzá all’apertura — la piramide di Kukulcán e l’eco che i maya hanno accordato apposta; i cenote: voragini nella pietra calcarea con acqua turchese — vi fate il bagno nella geologia, e la luce scende dall’alto a colonna. Mérida è una capitale coloniale bianchissima: salbutes, i taco con uovo e semi di zucca, e la sera sulle piazze si danza la salsa. Oaxaca è la capitale della gastronomia: mole negro, tamales in foglie di banana, mezcal con arancia e sale di gusano, come vuole il rituale. Puebla porta la ceramica Talavera. Le spiagge: Tulum con le rovine sulla scogliera, Isla Mujeres con l’acqua quieta. Tacos al pastor ad ogni angolo — non temete il piccante: imparerete. La gente saluta con facilità e spesso. Il soggiorno qui risulta gustoso in senso letterale.'},
  t:{ru:['Чичен-Ица — к открытию, до автобусов с побережья','Сеноты — с маской: под водой интереснее','Такос al pastor — там, где вертел с ананасом'],
     en:['Chichén Itzá at opening, before coast buses','Snorkel in the cenotes — underwater is better','Al pastor tacos: follow the pineapple spit'],
     it:['Chichén Itzá all’apertura, prima degli autobus','Snorkel nei cenote: sotto è meglio','I tacos al pastor: seguite lo spiedo d’ananas']}},
 {i:'brazil',n:{ru:'Бразилия',en:'Brazil',it:'Brasile'},r:{ru:'Америка',en:'America',it:'America'},s:{ru:'Бразилия — континент размером с привычку неспешного разговора. Рио: Копакабана, Сахарная голова на канатке к закату, Христос с горы Корковадо, который смотрит на город так, будто следит за счётом — и вечерние пляжи с футболом в четыре ворот. Самба здесь не жанр, а температура; в Лапе — бары с живыми оркестрами до утра. Амазония заслуживает второго дня, а Игуасу — все 275 водопадов в радиусе километра, «Глотка дьявола» с площадки, где вода работает как оркестр; бразильская сторона даёт панораму, аргентинская — близость; берите обе. Амазония: лодка по Рио-Негро, кайманы ночью с фонариком, розовые дельфины, лес, который дышит громче города. Салвадор — афро-бразильский пульс, капоэйра на террасах и жареные акраже с креветками. Кухня — пиканья на гриле, açaí со свежего рынка, кайпиринья со щедрым льдом. здесь говорят с ритмом, и вы поймёте больше, чем ожидали.',
en:'Brazil is a continent with the pace of an unhurried conversation. Rio: Copacabana, Sugarloaf by cable car at sunset, Christ the Redeemer looking down from Corcovado as if keeping score, and evening beaches where football is played to four goals. Samba here is not a genre but a temperature; in Lapa the bars keep live bands going until morning. Iguaçu is 275 waterfalls within a kilometre: the Devil’s Throat from a platform where the water works like an orchestra; the Brazilian side gives you the panorama, the Argentine side the close-ups — take both. The Amazon: a boat on the Rio Negro, caimans by torchlight at night, pink dolphins, and a forest that breathes louder than the city. Salvador is the Afro-Brazilian pulse — capoeira on the terraces and acarajé fried with shrimp. The food: picanha on the grill, açaí fresh from the market, and a caipirinha with generous ice. They speak Portuguese here with rhythm, and you will understand more than you expected to.',
it:'Il Brasile è un continente grande quanto l’abitudine delle conversazioni senza fretta. Rio: la Copacabana, il Pan di Zucchero in funivia al tramonto, il Cristo del Corcovado che guarda la città come se tenesse il punteggio — e le spiagge la sera, col futvole a quattro porte. La samba qui non è un genere, è la temperatura; a Lapa, bar con orchestre dal vivo fino al mattino. Iguaçu: 275 cascate in un raggio di un chilometro, la Gola del Diavolo dalla piattaforma dove l’acqua suona come un’orchestra; prendete entrambi i lati della frontiera — dal Brasile il panorama, dall’Argentina la vicinanza. L’Amazzonia: un battello sul Rio Negro, i caimani di notte con la torcia, i delfini rosa e una foresta che respira più forte della città. Salvador è il polso afro-brasiliano: capoeira sui terrazzi, acarajé fritto con i gamberi. In tavola: picanha alla griglia, açái dal mercato fresco e caipirinha con ghiaccio generoso. Il portoghese lo si parla a ritmo — e capirete più di quanto pensiate.'},
  t:{ru:['Сахарная голова — на закат, до очередей','Игуасу — обе стороны границы','Кайпиринья — с щедрым льдом'],
     en:['Sugarloaf at sunset, before the lines','Iguaçu from both sides of the border','Caipirinha with generous ice'],
     it:['Pan di Zucchero al tramonto, prima della fila','Iguaçu da entrambi i lati della frontiera','La caipirinha con ghiaccio generoso']}},
 {i:'peru',n:{ru:'Перу',en:'Peru',it:'Perù'},r:{ru:'Америка',en:'America',it:'America'},s:{ru:'Перу — страна высоты: здесь даже впечатления идут с акклиматизацией. Кузко — бывшая столица инков на 3400 метрах: стены инков несут колониальные балконы без раствора и шва, и они стоят после землетрясений, которые смеялись над цементом. Разгон: первый день — спокойный, мате-де-кока, чай, который и правда помогает. Мачу-Пикчу: автобус из Агуас-Кальентес к рассвету, туман поднимается, и город открывается по кадру; гида берите — история расшифровки стоит рассказа. Путь инков или поезд по живописной долине Урубамбы — оба вида честные. Виникунка — радужная гора на 5000 метров: минералы красят склоны в семь цветов, идти тяжело и красиво. озеро Титикака с плавучими островами урос — камыш, который живёт как город. Кухня — лучшая в Латинской Америке: севиче перуанское, ломо солтадо и 4000 сортов картофеля — не шутка, они их считали. чича морада, фиолетовая. Воздух тонкий, памятники плотные — Перу остаётся и в легких — тоже: воздух тонкий.',
en:'Peru is a country of altitude: even impressions come with acclimatisation. Cusco, the former Inca capital at 3,400 metres: Inca walls carry colonial balconies without mortar, and have stood through earthquakes that made short work of cement. Take the first day slow, with no itinerary — and mate de coca, a tea that genuinely helps. Machu Picchu: the bus from Aguas Calientes before dawn, fog lifting, the city appearing frame by frame from under the clouds; take a guide — the story pays for itself. Take the Inca Trail or the train up the scenic Urubamba valley — both honest. Vinicunca, the rainbow mountain at 5,000 metres: minerals paint the slopes in seven colours, the walk is hard and beautiful. Lake Titicaca holds the floating Uros islands — reeds living as a town. The food is the best in Latin America: Peruvian ceviche, lomo saltado and 4,000 varieties of potato — not a joke, they counted. Purple chicha morada to drink. The air is thin and the monuments dense — Peru leaves a mark, in the memory and in the lungs.',
it:'Il Perù è un paese d’altitudine: perfino le emozioni arrivano con l’acclimatazione. Cusco, ex capitale inca a 3400 metri: i muri inca reggono i balconi coloniali senza calce né giunto, e tengono dopo terremoti che hanno riso del cemento. Prima giornata in calma, e il mate de coca, l’infuso che aiuta davvero. Machu Picchu: l’autobus da Aguas Calientes all’alba, la nebbia si alza e la città si apre a fotogrammi; guida sì: la decodifica merita il racconto. O il Camino Inca, o il treno per la Valle Sacra dell’Urubamba — le due prospettive sono verità. Vinicunca, la montagna arcobaleno a 5000 metri: i minerali dipingono i pendii in sette colori — salita pesante e splendida. Il Titicaca con le isole galleggianti degli uros: un canneto che vive come una città. La cucina è la migliore d’America Latina: ceviche peruviano, lomo saltado e 4000 varietà di patate — non è scherzo, le hanno contate. La chicha morada è viola. L’aria è sottile, i monumenti densi: il Perù lascia una traccia nella memoria — e nei polmoni pure.'},
  t:{ru:['День разгона в Кузко — без маршрутов','Мачу-Пикчу — билеты за месяц и на рассвет','Кока-матэ — чай, который помогает'],
     en:['One easy day in Cusco — no itineraries','Machu Picchu tickets a month ahead, at dawn','Coca tea helps and is entirely legal here'],
     it:['Un giorno in Cusco senza tour','Biglietti per Machu Picchu con un mese d’anticipo, all’alba','Il tè di coca aiuta ed è perfettamente legale']}},
 {i:'usa',n:{ru:'США',en:'USA',it:'USA'},r:{ru:'Америка',en:'America',it:'America'},s:{ru:'США работают на двух масштабах, и путешествие собирает оба. Нью-Йорк: Манхэттен с парома Статен-Айленд — бесплатный, и статуя свободы по пути; Центральный парк, где бегают даже при снеге, Бродвей, метро, работающее 24 часа, и пицца slice на ходу — гражданский ритуал. Второй масштаб — юго-запад на машине: Гранд-Каньон на рассвете, когда тени рисуют слои породы по два миллиарда лет; Антилопа-каньон — волны песчаника внутри узкой щели; Монумент-Вэлли, где горизонт не заканчивается. Лас-Вегас — отдельный жанр. Йосемити с водопадами и секвойями — деревья размером с дом. Кухня — от diners с bottomless coffee до техасского барбекю с очередью в час дня, и каждый штат приправляет это своим акцентом. Чаевые — 18–20%, к ним привыкайте сразу. Дороги широкие, drive-through — гражданская магия, а каньоны — причина, по которой роуд-трип здесь делают второй и третий раз.',
en:'The USA runs on two scales, and a good trip takes in both. New York: Manhattan from the Staten Island ferry — free, with the Statue of Liberty along the way; Central Park, where people run even in the snow; a metro that never closes, and a slice of pizza eaten standing up — a civic ritual. The second scale is the Southwest by car: the Grand Canyon at sunrise, when the shadows draw out the layers of two billion years of rock; Antelope Canyon, waves of sandstone inside a narrow slot; Monument Valley, where the horizon refuses to end. Las Vegas is a genre of its own. Yosemite adds waterfalls and sequoias that make the cars in the lot look small. The food runs from diners with bottomless coffee to Texas barbecue with a queue at one in the afternoon. Tips are 18–20% — build the habit at once. The roads are wide, the drive-through is the country’s quiet civic magic, and the distances are exactly why the road trip was invented here.',
it:'Gli USA lavorano su due scale, e il viaggio gioca su entrambe. New York: Manhattan dal traghetto Staten Island — gratis, e con la Statua della Libertà per strada; il Central Park, dove si corre perfino sotto la neve, la metro che non chiude mai e la pizza a tranci mangiata a passi — un rito civico. La seconda scala è il sud-ovest in auto: il Grand Canyon all’alba, quando le ombre disegnano strati di roccia vecchi due miliardi d’anni; l’Antelope Canyon — onde d’arenaria dentro una fessura stretta; Monument Valley, dove l’orizzonte non finisce. Las Vegas è un genere a parte, se vi serve il contrasto. Yosemite, con le cascate e le sequoie giganti. Cucina: dai diner col caffè senza fondo al barbecue texano con la fila all’una pomeridiana. Le mance: 18–20 per cento — vi abituate da subito. Le strade sono larghe, e il drive-through è la magia civile del paese.'},
  t:{ru:['Манхэттен — с парома Статен-Айленд, бесплатно','Каньоны — на рассвете, до полуденной жары','Чаевые 18–20% — привыкайте сразу'],
     en:['Manhattan from the free Staten Island ferry','Canyons at sunrise, before midday heat','Tips are 18–20% — build the habit at once'],
     it:['Manhattan col traghetto gratuito di Staten Island','I canyon all’alba, prima del caldo di mezzogiorno','Mancia al 18–20%: prendetela subito come abitudine']}},
 {i:'cuba',n:{ru:'Куба',en:'Cuba',it:'Cuba'},r:{ru:'Америка',en:'America',it:'America'},s:{ru:'Куба — музей, который всё ещё работает, и вы живёте внутри. Гавана: Malecon — набережная длиной в восемь километров, где волны прыгают через парапет и город не обижается; классики 1950-х на каждом углу — Chevrolet с латунным мотором, который пережил три ремонта и весь XX век; старый город Гавана-Вьеха с облупленными пастельными фасадами. Мохито в Бодегита-дель-Медио: стены в автографах, включая Хемингуэя. Сальса здесь — не развлечение, а способ двигаться с музыкой; Casa de la Musica по вечерам собирает всех возрастов. Виньялес — долина с моготами, известняковыми стопками в зелёных полях, табачными фермами, где скручивают сигары руками — быстрее, чем вы читаете эти строки. пляжи Варадеро — белый порошок и бирюза. Еда — креольская: "старая одежда" из говядины (ropa vieja), рис с фасолью — moros y cristianos — и местное пиво. Живое — то слово, что здесь работает лучше всего.',
en:'Cuba is a museum that is still running, and you live inside it. Havana: the Malecón, an eight-kilometre embankment where the waves jump over the parapet and the city takes no offence; 1950s classics on every corner — a rebuilt Chevrolet engine that survived three repairs and the whole twentieth century; and Havana Vieja with peeling facades in pastel shades, like old film posters. A mojito at La Bodeguita del Medio, under walls covered in signatures — Hemingway and hundreds after him. Salsa here is not entertainment, it is a way of moving with the music; the Casa de la Música evenings gather every age at once. Viñales is a valley of mogotes — limestone stacks standing in green fields — and tobacco farms where cigars are rolled by hand faster than you read these lines. Varadero closes the story with powder-white sand and turquoise. The food is creole: ropa vieja, rice with beans going by the name moros y cristianos, and local beer. Carry cash — cards are an optional opinion. Alive is the word that works best here.',
it:'Cuba è un museo che continua a lavorare — e voi abitate dentro. L’Avana: il Malecón, otto chilometri di lungomare, dove le onde saltano il parapetto e alla città non importa; le classiche anni Cinquanta ad ogni angolo — una Chevrolet che ha attraversato tre riparazioni e un secolo intero; l’Habana Vieja con le facciate pastello, come vecchie locande, e il mojito alla Bodeguita del Medio, dove beveva Hemingway e le firme dei suoi seguaci coprono le pareti. La salsa qui non è un passatempo: è il modo di muoversi con la musica; la Casa de la Música la sera riunisce tutte le età. Viñales: la valle con i mogotes, le torri di calcare nei campi verdi, e le fattorie di tabacco, dove i sigari si arrotolano a mano, più in fretta di quanto leggete queste righe. Le spiagge di Varadero: polvere bianca e turchese. Cucina creola: ropa vieja, riso e fagioli che si chiamano moros y cristianos, e una birra locale. Il vocabolo che qui funziona meglio di tutti è vivo.'},
  t:{ru:['Мохито — в Бодегита-дель-Медио, у стен с подписями','Моготы Винталеса — с фермером, не из окна автобуса','Наличные — главный инструмент: карты порой не работают'],
     en:['Mojitos at La Bodeguita, walls covered with signatures','Viñales mogotes with a farmer, not from the bus window','Carry cash — cards are an optional opinion'],
     it:['Mojito alla Bodeguita, muri pieni di dediche','I mogotes di Viñales in fattoria, non dal finestrino','Contanti: le carte sono opinione facoltativa']}},
 {i:'uzbekistan',n:{ru:'Узбекистан',en:'Uzbekistan',it:'Uzbekistan'},r:{ru:'Азия',en:'Asia',it:'Asia'},s:{ru:'Узбекистан — Великий шёлковый путь, который работает по сей день и не требует визы. Самарканд: площадь Регистан — три медресе, бирюза куполов, изразцы, в которых узоры повторяются с математической честностью; ночью подсветка делает купола — парящими. Гур-Эмир — мавзолей Тамерлана, купол цвета ночного неба; Улугбек построил здесь обсерваторию, которая считала звёзды лучше большинства в XV веке. Бухара — живой город из глины: минарет Калон, караван-сарай, где теперь чайханы, торговые купола Токи-Заргарон, где продают ножи и шёлк; вечером — чай с лепёшкой, и вы понимаете, зачем людям медресе вместо парков. Хива — музей-крепость целиком: Ичан-Кала и минарет Ислама-Ходжи — самый высокий в Средней Азии. Плов в Ташкенте — центр плова: рис с нутом и морковью соломкой, и деликатность в том, что едят его в полдень, а готовят с рассвета. Мастерские Маргилана, где кокон варят так же, как сотни лет назад. Поезда быстрые: Ташкент—Самарканд — два с небольшим часа.',
en:'Uzbekistan is the Great Silk Road still working, and visa-free. Samarkand: the Registan — three madrasahs, turquoise domes, tile patterns repeated with mathematical honesty; at night the lighting makes the domes float. Gur-Emir, Tamerlane’s mausoleum, keeps a dome the colour of the night sky, and Ulugbek built an observatory that read the stars better than most in the fifteenth century. Bukhara is a living city of clay: the Kalyan minaret, caravanserais turned into teahouses, the trading domes of Toki Zargaron selling knives and silk; in the evening, tea with a flatbread — and you see why people need madrasahs instead of parks. Khiva is a fortress-museum entire: the Ichon-Qala walls and Islam Khoja — the tallest minaret in Central Asia. Plov at Tashkent’s central osh-markaz: rice with chickpeas, carrot cut into strips, cooked from dawn, eaten at noon — that is the delicacy. In Margilan, silk workshops still boil cocoons as they did centuries ago. The trains are quick: Tashkent–Samarkand in just over two hours.',
it:'L’Uzbekistan è la Via della Seta che funziona ancora oggi e non chiede visto. Samarcanda: la piazza Registan — tre madrase, cupole turchesi, maioliche che si ripetono con regolarità matematica; la sera l’illuminazione le fa librar. Il Gur-Emir, mausoleo di Tamerlano, con la cupola color cielo di notte; Ulug Beg costrui l’osservatorio che nel Quattrocento contava le stelle meglio di quasi tutti. Bucara è una città viva d’argilla: il minareto Kalon, un caravanserraglio che oggi è chaikhana, i bazar coperti di Toki-Zargaron, dove si vendono coltelli e seta; la sera, thè col pane tondo, e capite perché le madrase valgono più dei parchi. Khiva è un museo-fortezza intero: Itchan Kala, le mura e il minareto Islam Khoja, il più alto dell’Asia Centrale. A Tashkent, il centro del plov: riso con ceci e carota a julienne — la finezza: si mangia a mezzogiorno, si prepara dall’alba. A Margilan, nelle officine di seta, i bozzoli si cuociono come centinaia d’anni fa. I treni sono veloci: Tashkent–Samarcanda in poco più di due ore.'},
  t:{ru:['Регистан — днём и второй раз ночью','Плов — в центральном ош-марказе Ташкента','Поезд Ташкент—Самарканд — быстрее машины'],
     en:['Registan twice — by day and lit at night','Plov at the central osh-markaz in Tashkent','The Tashkent–Samarkand train beats the car'],
     it:['Il Registan due volte: di giorno e illuminato di sera','Il plov all’osh-markaz centrale di Tashkent','Il treno Tashkent—Samarcanda batte l’auto']}}
];
